_BUNDLE_SOURCES['whitebox.versions.v239_public_scenario_c06'] = '# Reproduced from Pilkwang Kim\'s public Kaggle Code:\n# https://www.kaggle.com/code/pilkwang/kaggriculture-scenario-aware-economic-policy\n"""Kaggriculture C06 reproduction of the updated scenario-aware policy.\n\nThe executable policy is unchanged from the attributed public release. This\nversion records the exact source used for paired validation and submission.\n"""\n\nfrom collections import deque\nimport math\n\n\n# Domain constants\n\nCROPS = {\n    "WHEAT": {\n        "seed": 10,\n        "first": 2,\n        "max_day": 4,\n        "max_yield": 6,\n        "ongoing": False,\n        "ripe": 4,\n        "last_plant": 24,\n    },\n    "CARROT": {\n        "seed": 20,\n        "first": 2,\n        "max_day": 3,\n        "max_yield": 4,\n        "ongoing": False,\n        "ripe": 3,\n        "last_plant": 25,\n    },\n    "TOMATO": {\n        "seed": 50,\n        "first": 8,\n        "max_day": 8,\n        "max_yield": 4,\n        "ongoing": True,\n        "interval": 1,\n        "ripe": 8,\n        "last_plant": 19,\n    },\n    "STRAWBERRY": {\n        "seed": 100,\n        "first": 10,\n        "max_day": 10,\n        "max_yield": 4,\n        "ongoing": True,\n        "interval": 2,\n        "ripe": 10,\n        "last_plant": 18,\n    },\n    "MELON": {\n        "seed": 80,\n        "first": 10,\n        "max_day": 12,\n        "max_yield": 6,\n        "ongoing": False,\n        "ripe": 10,\n        "last_plant": 18,\n    },\n}\n\nANIMALS = {\n    "GOOSE": {\n        "cost": 300,\n        "structure": "COOP",\n        "product": "EGG",\n        "first": 4,\n        "interval": 1,\n        "max_held": 4,\n    },\n    "COW": {\n        "cost": 400,\n        "structure": "PASTURE",\n        "product": "MILK",\n        "first": 8,\n        "interval": 2,\n        "max_held": 6,\n    },\n    "SHEEP": {\n        "cost": 500,\n        "structure": "PASTURE",\n        "product": "WOOL",\n        "first": 6,\n        "interval": 3,\n        "max_held": 6,\n    },\n}\n\nPRODUCTS = (\n    "WHEAT",\n    "CARROT",\n    "TOMATO",\n    "STRAWBERRY",\n    "MELON",\n    "EGG",\n    "MILK",\n    "WOOL",\n    "FERTILIZER",\n)\n\nMARKET = {\n    "WHEAT": (25, 400, "sqrt", 0.80, "log", 0.20),\n    "CARROT": (35, 450, "log", 0.20, "sqrt", 0.70),\n    "TOMATO": (60, 200, "linear", 0.40, "sqrt", 0.60),\n    "STRAWBERRY": (120, 100, "sqrt", 0.70, "linear", 1.60),\n    "MELON": (250, 300, "log", 0.20, "sq", 3.60),\n    "EGG": (50, 332, "linear", 0.40, "log", 0.20),\n    "MILK": (160, 122, "sqrt", 0.60, "linear", 1.60),\n    "WOOL": (200, 105, "log", 0.20, "sq", 3.20),\n    "FERTILIZER": (100, 200, "linear", 0.40, "linear", 0.40),\n}\n\nSHOPS = {\n    "BAKERY": ("EGG", "WHEAT"),\n    "PIZZA_SHOP": ("MILK", "TOMATO", "WHEAT"),\n    "BRUNCH_SPOT": ("EGG", "WHEAT", "STRAWBERRY"),\n    "YARN_STORE": ("WOOL",),\n    "ICE_CREAM_SHOP": ("STRAWBERRY", "MILK", "WHEAT"),\n    "PET_CAFE": ("CARROT",),\n    "SMOOTHIE_SHOP": ("STRAWBERRY", "MILK"),\n    "FARMERS_MARKET": ("WHEAT", "CARROT", "TOMATO", "STRAWBERRY"),\n}\n\nRESERVE_FRACTION = {\n    "WHEAT": 0.68,\n    "CARROT": 0.55,\n    "TOMATO": 0.50,\n    "STRAWBERRY": 0.48,\n    "MELON": 0.58,\n    "EGG": 0.65,\n    "MILK": 0.42,\n    "WOOL": 0.40,\n    "FERTILIZER": 0.18,\n}\n\nMOVES = (\n    ("NORTH", 0, -1),\n    ("WEST", -1, 0),\n    ("SOUTH", 0, 1),\n    ("EAST", 1, 0),\n)\n\nLAND_PRICES = (1000, 2000, 4000)\nMARKET_I0 = 10000\nTOTAL_DAYS = 30\nMAX_MARKET_ORDERS = 10\nMAX_HANDS = 12\nCORE_HERD_SEQUENCE = ("COW", "COW", "COW", "SHEEP")\nLIVESTOCK_TYPES = ("COW", "SHEEP")\nCORE_HERD = len(CORE_HERD_SEQUENCE)\nMID_HERD = 11\nTARGET_HERD = 15\nHERD_EXPANSION_DAY = 7\nHERD_FINAL_DAY = 11\nANIMAL_PURCHASE_LAST_DAY = 18\nANIMAL_SLOTS = {"NW": 4, "NE": 7, "SW": 4, "SE": 0}\nCROP_MIX = {\n    "NW": {"MELON": 10, "WHEAT": 4, "CARROT": 2},\n    "NE": {"WHEAT": 4, "CARROT": 1},\n    "SW": {"WHEAT": 4, "CARROT": 1},\n    "SE": {"WHEAT": 5, "CARROT": 2},\n}\nMELON_TILES_MIN = 8\nMELON_TILES_BASE = 10\nMELON_TILES_MAX = 12\nMAX_EXTRA_LAND = 2\nCASH_RESERVE = 250\nLIQUIDATION_TURNS = 22\nSHED_CAPACITY = 100\nTRAVEL_COST = 8.0\nFEED_STOCK_DAYS = 3\nLAND_OPEN_DAYS = (5, 9)\nDROP_PRESSURE_THRESHOLD = 80\nDROP_UNIT_THRESHOLD = 20\nDROP_VALUE_THRESHOLD = 2500\nCASH_DROP_VALUE_THRESHOLD = 400\nQUADRANT_CROSS_COST = 0.0\n# Optional field work has a public continuity cost when it abandons the\n# worker\'s current quadrant.  The default is zero so the audited V361 policy\n# remains unchanged; research wrappers may enable the explicit challenger.\nOPTIONAL_QUADRANT_CROSS_COST = 0.0\nTARGET_STICKINESS_BONUS = 0.0\nSAME_TILE_COMPLETION_BONUS = 0.0\nMOVE_REVERSAL_PENALTY = 0.0\nGLOBAL_PAIR_MATCHING = False\nTERRITORY_MISMATCH_PENALTY = 0.0\nMISSION_PRESERVING_EXCHANGE = False\nMISSION_PRESERVING_GLOBAL_ASSIGNMENT = False\nSALE_CASH_FACTOR = 0.85\nCOMMITTED_WORK_SALE_CASH_FACTOR = 0.85\nPRIORITY_BONUS = {\n    -1: 120_000.0,\n    0: 100_000.0,\n    1: 1_500.0,\n    2: 750.0,\n    3: 250.0,\n    4: 0.0,\n    5: -100.0,\n}\n\n_TARGET_CERTIFICATES = {}\n_MOMENTUM_CERTIFICATES = {}\n_TERRITORY_CERTIFICATES = {}\n_OPPOSITE_MOVE = {\n    "NORTH": "SOUTH",\n    "SOUTH": "NORTH",\n    "EAST": "WEST",\n    "WEST": "EAST",\n}\n\n\n# Configuration, pricing, and routing helpers\n\ndef _cfg(config, key, default):\n    if config is None:\n        return default\n    if isinstance(config, dict):\n        return config.get(key, default)\n    return getattr(config, key, default)\n\n\ndef _shape(name, value):\n    value = max(0.0, float(value))\n    if name == "linear":\n        return value\n    if name == "sq":\n        return value * value\n    if name == "sqrt":\n        return math.sqrt(value)\n    if name == "log":\n        return math.log1p(value)\n    if name == "log10":\n        return math.log10(1.0 + value)\n    return value\n\n\ndef _market_parameters(obs, item):\n    base, throughput, below_fn, below_move, above_fn, above_move = MARKET[item]\n    custom = (((obs or {}).get("market", {}) or {}).get("params", {}) or {}).get(\n        item, {}\n    )\n    return (\n        float(custom.get("base", base)),\n        float(custom.get("T", throughput)),\n        str(custom.get("below_func", below_fn)),\n        float(custom.get("below_target", below_move)),\n        str(custom.get("above_func", above_fn)),\n        float(custom.get("above_target", above_move)),\n        float(custom.get("I0", MARKET_I0)),\n    )\n\n\ndef _price_at(item, inventory, obs=None):\n    (\n        base,\n        throughput,\n        below_fn,\n        below_move,\n        above_fn,\n        above_move,\n        equilibrium,\n    ) = _market_parameters(obs, item)\n    if inventory < equilibrium:\n        amplitude = below_move * base / max(1e-9, _shape(below_fn, throughput))\n        value = base + amplitude * _shape(below_fn, equilibrium - inventory)\n    else:\n        amplitude = above_move * base / max(1e-9, _shape(above_fn, throughput))\n        value = base - amplitude * _shape(above_fn, inventory - equilibrium)\n    return max(1, int(round(value)))\n\n\ndef _town_demand_per_day(obs, item):\n    day = int((obs or {}).get("day", 0) or 0)\n    center = 0 if item == "FERTILIZER" else 2 * (\n        4 if day >= 20 else 2 if day >= 10 else 1\n    )\n    shop = 0\n    for name in (((obs or {}).get("town", {}) or {}).get(\n        "unlocked_shops", []\n    ) or []):\n        products = SHOPS.get(name, ())\n        if item in products:\n            shop += 12 if len(products) == 1 else 6\n    return center + shop\n\n\ndef _opponent_visible_supply(obs, item, horizon=1):\n    player = int((obs or {}).get("player", 0) or 0)\n    day = int((obs or {}).get("day", 0) or 0)\n    animal_for = {"EGG": "GOOSE", "MILK": "COW", "WOOL": "SHEEP"}\n    total = 0\n    for index, farm in enumerate((obs or {}).get("farms", []) or []):\n        if index == player:\n            continue\n        for row in farm.get("tiles", []) or []:\n            for tile in row:\n                if not isinstance(tile, dict):\n                    continue\n                if (\n                    item in CROPS\n                    and tile.get("kind") == "PLANT"\n                    and tile.get("crop") == item\n                ):\n                    rule = CROPS[item]\n                    planted = tile.get("planted_day")\n                    planted_day = day if planted is None else int(planted)\n                    age = day - planted_day\n                    held = int(tile.get("yield_units", 0) or 0)\n                    if held > 0 and age >= rule["first"]:\n                        total += held\n                    elif age + horizon >= rule["ripe"]:\n                        total += max(1, min(rule["max_yield"], held + horizon))\n                elif item in animal_for and tile.get("animal") == animal_for[item]:\n                    total += int(tile.get("yield_units", 0) or 0)\n                    if horizon > 0:\n                        total += min(2 * horizon, ANIMALS.get(\n                            tile.get("animal"), {"max_held": 4}\n                        )["max_held"])\n    return total\n\n\ndef _distance(a, b):\n    return abs(int(a[0]) - int(b[0])) + abs(int(a[1]) - int(b[1]))\n\n\ndef _shed_tiles(board_size, tiles=None):\n    half = board_size // 2\n    candidates = (\n        (half - 1, half - 1),\n        (half, half - 1),\n        (half - 1, half),\n        (half, half),\n    )\n    if tiles is None:\n        return candidates\n    accessible = tuple(\n        position\n        for position in candidates\n        if tiles[position[1]][position[0]] != "LOCKED"\n    )\n    return accessible or candidates[:1]\n\n\ndef _nearest_shed(position, board_size, tiles=None):\n    return min(\n        _shed_tiles(board_size, tiles),\n        key=lambda target: (_distance(position, target), target[1], target[0]),\n    )\n\n\ndef _bfs_first_step(tiles, source, target):\n    source = (int(source[0]), int(source[1]))\n    target = (int(target[0]), int(target[1]))\n    if source == target:\n        return ["PASS"]\n    board_size = len(tiles)\n    queue = deque([source])\n    parent = {source: None}\n    parent_move = {}\n    while queue:\n        current = queue.popleft()\n        if current == target:\n            break\n        for name, dx, dy in MOVES:\n            nxt = (current[0] + dx, current[1] + dy)\n            if not (0 <= nxt[0] < board_size and 0 <= nxt[1] < board_size):\n                continue\n            if nxt in parent or tiles[nxt[1]][nxt[0]] == "LOCKED":\n                continue\n            parent[nxt] = current\n            parent_move[nxt] = name\n            queue.append(nxt)\n    if target not in parent:\n        return ["PASS"]\n    current = target\n    while parent[current] != source:\n        current = parent[current]\n        if current is None:\n            return ["PASS"]\n    return [parent_move[current]]\n\n\ndef _melon_target(obs):\n    prices = ((obs.get("market", {}) or {}).get("prices", {}) or {})\n    price = int(prices.get("MELON", MARKET["MELON"][0]) or MARKET["MELON"][0])\n    opponent_tiles = 0\n    player = int(obs.get("player", 0) or 0)\n    for index, other in enumerate(obs.get("farms", []) or []):\n        if index == player:\n            continue\n        for row in other.get("tiles", []) or []:\n            opponent_tiles += sum(\n                isinstance(tile, dict)\n                and tile.get("kind") == "PLANT"\n                and tile.get("crop") == "MELON"\n                for tile in row\n            )\n    if price >= 300 and opponent_tiles <= 5:\n        return MELON_TILES_MAX\n    if price <= 170 or opponent_tiles >= 12:\n        return MELON_TILES_MIN\n    if opponent_tiles >= 9:\n        return MELON_TILES_BASE - 1\n    return MELON_TILES_BASE\n\n\ndef _private_item_total(private, item):\n    total = int((private.get("shed", {}) or {}).get(item, 0) or 0)\n    for inventory in private.get("inventories", []) or []:\n        total += int((inventory or {}).get(item, 0) or 0)\n    return total\n\n\ndef _farm_animal_counts(farm):\n    counts = {animal: 0 for animal in ANIMALS}\n    for row in farm.get("tiles", []) or []:\n        for tile in row:\n            if isinstance(tile, dict) and tile.get("animal") in counts:\n                counts[tile["animal"]] += 1\n    return counts\n\n\ndef _opponent_animal_counts(obs):\n    player = int(obs.get("player", 0) or 0)\n    counts = {animal: 0 for animal in ANIMALS}\n    for index, farm in enumerate(obs.get("farms", []) or []):\n        if index == player:\n            continue\n        visible = _farm_animal_counts(farm)\n        for animal, count in visible.items():\n            counts[animal] += count\n    return counts\n\n\ndef _livestock_score(obs, animal, own_count, opponent_count):\n    rule = ANIMALS[animal]\n    product = rule["product"]\n    prices = ((obs.get("market", {}) or {}).get("prices", {}) or {})\n    price = float(prices.get(product, MARKET[product][0]) or MARKET[product][0])\n    normalized_price = price / float(MARKET[product][0])\n    demand_support = 1.0 + 0.012 * _town_demand_per_day(obs, product)\n    crowding = 1.0 + 0.18 * opponent_count + 0.08 * own_count\n    return normalized_price * demand_support / crowding\n\n\ndef _quadrant_of(position, board_size):\n    x, y = position\n    half = board_size // 2\n    return ("N" if y < half else "S") + ("W" if x < half else "E")\n\n\ndef _reserved_animal_slots(farm):\n    tiles = farm.get("tiles", []) or []\n    board_size = len(tiles)\n    unlocked = set(farm.get("unlocked_quadrants", []) or ["NW"])\n    sheds = _shed_tiles(board_size, tiles)\n    slots = []\n    by_quadrant = {}\n    for quadrant in ("NW", "NE", "SW", "SE"):\n        if quadrant not in unlocked:\n            continue\n        cells = []\n        for y, row in enumerate(tiles):\n            for x, tile in enumerate(row):\n                if tile == "LOCKED" or _quadrant_of((x, y), board_size) != quadrant:\n                    continue\n                distance = min(_distance((x, y), shed) for shed in sheds)\n                cells.append((distance, y, x))\n        cells.sort()\n        count = min(ANIMAL_SLOTS[quadrant], len(cells))\n        selected = [(x, y) for _, y, x in cells[:count]]\n        by_quadrant[quadrant] = {\n            "reserved": selected,\n            "crops": [(x, y) for _, y, x in cells[count:]],\n        }\n        slots.extend(selected)\n    return slots, by_quadrant\n\n\ndef _herd_targets(obs, farm, private, capacity):\n    day = int(obs.get("day", 0) or 0)\n    left = TOTAL_DAYS - day\n    placed = _farm_animal_counts(farm)\n    owned = {\n        animal: placed[animal] + _private_item_total(private, animal)\n        for animal in LIVESTOCK_TYPES\n    }\n    if day < HERD_EXPANSION_DAY:\n        stage_target = CORE_HERD\n    elif day < HERD_FINAL_DAY:\n        stage_target = MID_HERD\n    else:\n        stage_target = TARGET_HERD\n    if day > ANIMAL_PURCHASE_LAST_DAY or left < 8:\n        stage_target = sum(owned.values())\n    target_total = min(capacity, max(sum(owned.values()), stage_target))\n\n    targets = {\n        animal: max(\n            CORE_HERD_SEQUENCE.count(animal)\n            if target_total >= CORE_HERD\n            else 0,\n            owned[animal],\n        )\n        for animal in LIVESTOCK_TYPES\n    }\n    opponents = _opponent_animal_counts(obs)\n    while sum(targets.values()) < target_total:\n        animal = max(\n            LIVESTOCK_TYPES,\n            key=lambda name: (\n                _livestock_score(\n                    obs,\n                    name,\n                    targets[name],\n                    opponents[name],\n                ),\n                -targets[name],\n                name == "COW",\n            ),\n        )\n        targets[animal] += 1\n    return targets\n\n\ndef _role_plan(obs, farm):\n    private = obs.get("private", {}) or {}\n    tiles = farm.get("tiles", []) or []\n    animal_slots, zones = _reserved_animal_slots(farm)\n    targets = _herd_targets(obs, farm, private, len(animal_slots))\n    desired_animals = min(len(animal_slots), sum(targets.values()))\n    active_slots = list(animal_slots[:desired_animals])\n    for position in animal_slots:\n        x, y = position\n        tile = tiles[y][x]\n        if isinstance(tile, dict) and "animal" in tile and position not in active_slots:\n            active_slots.append(position)\n\n    assigned = {animal: 0 for animal in LIVESTOCK_TYPES}\n    roles = {}\n    core_sequence = CORE_HERD_SEQUENCE\n    for index, position in enumerate(active_slots):\n        x, y = position\n        tile = tiles[y][x]\n        actual = tile.get("animal") if isinstance(tile, dict) else None\n        if actual in assigned:\n            animal = actual\n        elif index < len(core_sequence) and assigned[core_sequence[index]] < targets[\n            core_sequence[index]\n        ]:\n            animal = core_sequence[index]\n        else:\n            animal = max(\n                LIVESTOCK_TYPES,\n                key=lambda name: (\n                    targets[name] - assigned[name],\n                    _private_item_total(private, name),\n                    name == "COW",\n                ),\n            )\n        roles[position] = ("ANIMAL", animal)\n        assigned[animal] += 1\n\n    melon_target = _melon_target(obs)\n    for quadrant in ("NW", "NE", "SW", "SE"):\n        zone = zones.get(quadrant)\n        if not zone:\n            continue\n        cells = zone["crops"]\n        fixed = dict(CROP_MIX[quadrant])\n        if quadrant == "NW":\n            fixed["MELON"] = min(melon_target, len(cells))\n        strawberry_count = max(0, len(cells) - sum(fixed.values()))\n        sequence = []\n        if quadrant == "NW":\n            sequence.extend(["MELON"] * fixed.get("MELON", 0))\n        sequence.extend(["STRAWBERRY"] * strawberry_count)\n        sequence.extend(["WHEAT"] * fixed.get("WHEAT", 0))\n        sequence.extend(["CARROT"] * fixed.get("CARROT", 0))\n        if quadrant != "NW":\n            sequence.extend(["MELON"] * fixed.get("MELON", 0))\n        for position, crop in zip(cells, sequence):\n            roles[position] = ("CROP", crop)\n    return roles\n\n\n# Observation summaries and job generation\n\ndef _inventory_total(inventory, excluded=()):\n    return sum(\n        int(value)\n        for item, value in (inventory or {}).items()\n        if item not in excluded and isinstance(value, (int, float)) and value > 0\n    )\n\n\ndef _survey(farm, private, roles=None, day=0):\n    summary = {\n        "animals": 0,\n        "unfed": 0,\n        "at_risk_animals": 0,\n        "at_risk_crops": 0,\n        "open_structures": 0,\n        "structures_todo": 0,\n        "plants": 0,\n        "plantable": 0,\n        "weeds": 0,\n    }\n    for row in farm.get("tiles", []) or []:\n        for tile in row:\n            if not isinstance(tile, dict):\n                continue\n            if "animal" in tile:\n                summary["animals"] += 1\n                if not tile.get("fed_today", False):\n                    summary["unfed"] += 1\n                if int(tile.get("consecutive_unfed", 0) or 0) >= 1:\n                    summary["at_risk_animals"] += 1\n            elif tile.get("kind") in {"COOP", "PASTURE"}:\n                summary["open_structures"] += 1\n            elif tile.get("kind") == "PLANT":\n                summary["plants"] += 1\n                if int(tile.get("consecutive_unwatered", 0) or 0) >= 1:\n                    summary["at_risk_crops"] += 1\n            elif tile.get("kind") == "WEED":\n                summary["weeds"] += 1\n\n    if roles:\n        for (x, y), (kind, item) in roles.items():\n            tile = farm["tiles"][y][x]\n            if kind == "ANIMAL" and tile is None:\n                summary["structures_todo"] += 1\n            elif (\n                kind == "CROP"\n                and tile is None\n                and day <= CROPS[item]["last_plant"]\n            ):\n                summary["plantable"] += 1\n\n    summary["wheat_stock"] = int((private.get("shed", {}) or {}).get("WHEAT", 0))\n    summary["animal_stock"] = {\n        animal: int((private.get("shed", {}) or {}).get(animal, 0) or 0)\n        for animal in ANIMALS\n    }\n    summary["shed_load"] = sum(\n        max(0, int(value or 0))\n        for value in (private.get("shed", {}) or {}).values()\n    )\n    summary["carried_load"] = 0\n    for inventory in private.get("inventories", []) or []:\n        summary["wheat_stock"] += int((inventory or {}).get("WHEAT", 0))\n        for animal in ANIMALS:\n            summary["animal_stock"][animal] += int(\n                (inventory or {}).get(animal, 0) or 0\n            )\n        summary["carried_load"] += _inventory_total(inventory)\n    return summary\n\n\ndef _policy_phase(obs, farm, private, summary):\n    day = int(obs.get("day", 0) or 0)\n    step = int(obs.get("step", day * 24 + int(obs.get("hour", 0) or 0)) or 0)\n    actions_left = max(0, 719 - step)\n    if actions_left <= LIQUIDATION_TURNS:\n        return "LIQUIDATE"\n    workers = 1 + len(farm.get("hands", []) or [])\n    if (\n        summary["at_risk_animals"] + summary["at_risk_crops"] > workers\n        or summary["shed_load"] + summary["carried_load"] >= 95\n    ):\n        return "CRISIS"\n    if day <= 4:\n        return "BOOTSTRAP"\n    if day <= 21:\n        return "COMPOUND"\n    return "REALIZE"\n\n\ndef _add_job(\n    jobs,\n    priority,\n    value,\n    target,\n    action,\n    need=None,\n    reason="",\n    latest_hour=23,\n):\n    jobs.append(\n        {\n            "priority": int(priority),\n            "value": float(value),\n            "target": tuple(target),\n            "action": list(action),\n            "need": need,\n            "reason": str(reason),\n            "latest_hour": int(latest_hour),\n        }\n    )\n\n\ndef _animal_produces_tonight(tile, rule, day):\n    next_day = int(day) + 1\n    placed_day = int(tile.get("placed_day", day) or 0)\n    days_since_first = next_day - placed_day - int(rule["first"])\n    return (\n        days_since_first >= 0\n        and days_since_first % int(rule["interval"]) == 0\n    )\n\n\ndef _crop_jobs(obs, jobs, tile, target, day, liquidation):\n    crop = tile.get("crop")\n    rule = CROPS.get(crop)\n    if rule is None:\n        return\n    prices = ((obs.get("market", {}) or {}).get("prices", {}) or {})\n    price = float(prices.get(crop, MARKET[crop][0]) or MARKET[crop][0])\n    age = day - int(tile.get("planted_day", day))\n    amount = int(tile.get("yield_units", 0) or 0)\n    watered = bool(tile.get("watered_today", False))\n    drought = int(tile.get("consecutive_unwatered", 0) or 0)\n    critical = drought >= 1\n\n    if liquidation:\n        if amount > 0 and age >= rule["first"]:\n            _add_job(\n                jobs,\n                0,\n                amount * price,\n                target,\n                ("HARVEST",),\n                reason="terminal_harvest",\n            )\n        return\n\n    if critical and not watered:\n        protected = max(amount, rule["max_yield"] * 0.7) * price\n        _add_job(\n            jobs,\n            0,\n            protected,\n            target,\n            ("WATER",),\n            reason="critical_water",\n        )\n        return\n\n    if rule["ongoing"]:\n        next_day = day + 1\n        interval = max(1, int(rule.get("interval", 1)))\n        days_since_first = (\n            next_day - int(tile.get("planted_day", day)) - rule["first"]\n        )\n        production_index = (\n            days_since_first // interval + 1 if days_since_first >= 0 else 0\n        )\n        produces_tonight = (\n            days_since_first >= 0\n            and days_since_first % interval == 0\n            and production_index <= rule["max_yield"]\n        )\n        fertilized_until = tile.get("fertilized_until_day", -1)\n        fertilized_until = (\n            -1 if fertilized_until is None else int(fertilized_until)\n        )\n        if (\n            crop == "STRAWBERRY"\n            and produces_tonight\n            and fertilized_until < day\n        ):\n            _add_job(\n                jobs,\n                2,\n                max(100.0, price),\n                target,\n                ("FERTILIZE",),\n                need="FERTILIZER",\n                reason="strawberry_production_fertilizer",\n            )\n        if amount >= rule["max_yield"] - 1 or (amount > 0 and day >= 27):\n            _add_job(\n                jobs,\n                2,\n                amount * price,\n                target,\n                ("HARVEST",),\n                reason="ongoing_harvest",\n            )\n        elif not watered and age >= rule["first"] - 1:\n            _add_job(\n                jobs,\n                3,\n                price,\n                target,\n                ("WATER",),\n                reason="ongoing_water",\n            )\n        return\n\n    ripe = age >= rule["ripe"] and amount > 0\n    in_growth_window = (rule["max_day"] + 1) // 2 <= age <= rule["max_day"]\n    if ripe:\n        if in_growth_window and not watered and amount < rule["max_yield"]:\n            _add_job(\n                jobs,\n                1,\n                price,\n                target,\n                ("WATER",),\n                reason="final_growth_water",\n            )\n        else:\n            _add_job(\n                jobs,\n                2,\n                amount * price,\n                target,\n                ("HARVEST",),\n                reason="ripe_harvest",\n            )\n    elif in_growth_window and not watered:\n        _add_job(\n            jobs,\n            3,\n            price,\n            target,\n            ("WATER",),\n            reason="yield_water",\n        )\n\n\ndef _field_jobs(obs, farm, private, roles, liquidation):\n    day = int(obs.get("day", 0) or 0)\n    hour = int(obs.get("hour", 0) or 0)\n    left = TOTAL_DAYS - day\n    tiles = farm["tiles"]\n    seeds = dict(private.get("seeds", {}) or {})\n    prices = ((obs.get("market", {}) or {}).get("prices", {}) or {})\n    jobs = []\n    planned_roles = dict(roles)\n    for y, row in enumerate(tiles):\n        for x, tile in enumerate(row):\n            if not isinstance(tile, dict) or (x, y) in planned_roles:\n                continue\n            if tile.get("kind") == "PLANT" and tile.get("crop") in CROPS:\n                planned_roles[(x, y)] = ("CROP", tile["crop"])\n            elif tile.get("animal") in ANIMALS:\n                planned_roles[(x, y)] = ("ANIMAL", tile["animal"])\n\n    for target, role in planned_roles.items():\n        x, y = target\n        tile = tiles[y][x]\n        role_kind, role_item = role\n\n        if tile is None:\n            if liquidation:\n                continue\n            if role_kind == "ANIMAL":\n                animal_rule = ANIMALS[role_item]\n                if left >= animal_rule["first"] + 2:\n                    _add_job(\n                        jobs,\n                        3,\n                        420,\n                        target,\n                        ("BUILD_" + animal_rule["structure"],),\n                        reason="build_" + animal_rule["structure"].lower(),\n                        latest_hour=22,\n                    )\n            elif (\n                hour <= 22\n                and day <= CROPS[role_item]["last_plant"]\n                and seeds.get(role_item, 0) > 0\n            ):\n                rule = CROPS[role_item]\n                expected = 4 if role_item == "WHEAT" else rule["max_yield"]\n                price = float(\n                    prices.get(role_item, MARKET[role_item][0])\n                    or MARKET[role_item][0]\n                )\n                value = max(40, 0.65 * expected * price - rule["seed"])\n                _add_job(\n                    jobs,\n                    4,\n                    value,\n                    target,\n                    ("PLANT", role_item),\n                    reason="plant_" + role_item,\n                    latest_hour=22,\n                )\n            continue\n\n        if not isinstance(tile, dict):\n            continue\n        kind = tile.get("kind")\n        if role_kind == "ANIMAL" and kind in {"WEED", "PLANT"}:\n            if not liquidation:\n                _add_job(\n                    jobs,\n                    2,\n                    500,\n                    target,\n                    ("DIG",),\n                    reason="clear_animal_slot",\n                    latest_hour=22,\n                )\n            continue\n        if kind == "WEED":\n            if not liquidation:\n                _add_job(\n                    jobs,\n                    4,\n                    120 if left > 5 else 10,\n                    target,\n                    ("DIG",),\n                    reason="dig_weed",\n                    latest_hour=22,\n                )\n            continue\n        if kind == "PLANT":\n            _crop_jobs(obs, jobs, tile, target, day, liquidation)\n            continue\n        if (\n            role_kind == "ANIMAL"\n            and kind == ANIMALS[role_item]["structure"]\n            and "animal" not in tile\n        ):\n            if not liquidation:\n                _add_job(\n                    jobs,\n                    1,\n                    900,\n                    target,\n                    ("PLACE", role_item),\n                    need=role_item,\n                    reason="place_" + role_item.lower(),\n                )\n            continue\n        if (\n            role_kind == "ANIMAL"\n            and kind in {"COOP", "PASTURE"}\n            and kind != ANIMALS[role_item]["structure"]\n            and "animal" not in tile\n        ):\n            if not liquidation:\n                _add_job(\n                    jobs,\n                    3,\n                    250,\n                    target,\n                    ("DIG",),\n                    reason="replace_incompatible_structure",\n                )\n            continue\n        if "animal" not in tile:\n            continue\n        if liquidation:\n            if int(tile.get("yield_units", 0) or 0) > 0:\n                product = ANIMALS.get(\n                    tile.get("animal"), ANIMALS["GOOSE"]\n                )["product"]\n                value = int(tile.get("yield_units", 0) or 0) * float(\n                    prices.get(product, MARKET[product][0])\n                    or MARKET[product][0]\n                )\n                _add_job(\n                    jobs,\n                    0,\n                    value,\n                    target,\n                    ("HARVEST",),\n                    reason="terminal_animal",\n                )\n            if tile.get("fertilizer_available", False):\n                _add_job(\n                    jobs,\n                    0,\n                    float(\n                        prices.get("FERTILIZER", MARKET["FERTILIZER"][0])\n                        or MARKET["FERTILIZER"][0]\n                    ),\n                    target,\n                    ("COLLECT_FERTILIZER",),\n                    reason="terminal_fertilizer",\n                )\n            continue\n        if not tile.get("fed_today", False):\n            risk = int(tile.get("consecutive_unfed", 0) or 0) >= 1\n            _add_job(\n                jobs,\n                0 if risk else 1,\n                900 if risk else 260,\n                target,\n                ("FEED",),\n                need="WHEAT",\n                reason="critical_feed" if risk else "feed",\n            )\n        held = int(tile.get("yield_units", 0) or 0)\n        animal_rule = ANIMALS.get(tile.get("animal"), ANIMALS["GOOSE"])\n        product = animal_rule["product"]\n        pending_care = int(tile.get("pending_care_bonus", 0) or 0)\n        produces_tonight = _animal_produces_tonight(\n            tile, animal_rule, day\n        )\n        production_gain = 1 + pending_care if produces_tonight else 0\n        if held > 0 and (\n            held >= 3\n            or held + production_gain >= animal_rule["max_held"]\n            or day >= 27\n        ):\n            _add_job(\n                jobs,\n                2,\n                held\n                * float(\n                    prices.get(product, MARKET[product][0])\n                    or MARKET[product][0]\n                ),\n                target,\n                ("HARVEST",),\n                reason="animal_harvest",\n            )\n        if tile.get("fertilizer_available", False):\n            _add_job(\n                jobs,\n                2,\n                float(\n                    prices.get("FERTILIZER", MARKET["FERTILIZER"][0])\n                    or MARKET["FERTILIZER"][0]\n                ),\n                target,\n                ("COLLECT_FERTILIZER",),\n                reason="fertilizer",\n            )\n        if (\n            not tile.get("cared_today", False)\n            and day <= 27\n            and held\n            + (0 if produces_tonight else pending_care)\n            + 1\n            < animal_rule["max_held"]\n            and float(\n                prices.get(product, MARKET[product][0])\n                or MARKET[product][0]\n            ) >= 20\n        ):\n            _add_job(\n                jobs,\n                3,\n                float(\n                    prices.get(product, MARKET[product][0])\n                    or MARKET[product][0]\n                ),\n                target,\n                ("CARE",),\n                reason="care",\n            )\n    return jobs\n\n\ndef _terminal_feasible(position, target, tiles, actions_left):\n    board_size = len(tiles)\n    return (\n        _distance(position, target)\n        + 1\n        + min(\n            _distance(target, shed)\n            for shed in _shed_tiles(board_size, tiles)\n        )\n        + 1\n        <= actions_left\n    )\n\n\ndef _mission_conflict_key(mission_index, mission, target, liquidation):\n    if mission["kind"] != "FIELD":\n        return ("MISSION", int(mission_index))\n    operation = mission["action"][0]\n    if (\n        liquidation\n        and operation in {"HARVEST", "COLLECT_FERTILIZER"}\n    ) or operation == "FERTILIZE":\n        return ("FIELD_OP", tuple(target), operation)\n    return ("FIELD", tuple(target))\n\n\ndef _hungarian_min_cost(costs):\n    """Rectangular Hungarian assignment for rows <= columns."""\n    row_count = len(costs)\n    column_count = len(costs[0]) if costs else 0\n    if row_count == 0:\n        return []\n    potentials_rows = [0.0] * (row_count + 1)\n    potentials_columns = [0.0] * (column_count + 1)\n    matched_row = [0] * (column_count + 1)\n    previous_column = [0] * (column_count + 1)\n    for row in range(1, row_count + 1):\n        matched_row[0] = row\n        column = 0\n        minimum = [float("inf")] * (column_count + 1)\n        used = [False] * (column_count + 1)\n        while True:\n            used[column] = True\n            active_row = matched_row[column]\n            delta = float("inf")\n            next_column = 0\n            for candidate in range(1, column_count + 1):\n                if used[candidate]:\n                    continue\n                reduced = (\n                    float(costs[active_row - 1][candidate - 1])\n                    - potentials_rows[active_row]\n                    - potentials_columns[candidate]\n                )\n                if reduced < minimum[candidate]:\n                    minimum[candidate] = reduced\n                    previous_column[candidate] = column\n                if minimum[candidate] < delta:\n                    delta = minimum[candidate]\n                    next_column = candidate\n            for candidate in range(column_count + 1):\n                if used[candidate]:\n                    potentials_rows[matched_row[candidate]] += delta\n                    potentials_columns[candidate] -= delta\n                else:\n                    minimum[candidate] -= delta\n            column = next_column\n            if matched_row[column] == 0:\n                break\n        while True:\n            previous = previous_column[column]\n            matched_row[column] = matched_row[previous]\n            column = previous\n            if column == 0:\n                break\n    assignment = [-1] * row_count\n    for column in range(1, column_count + 1):\n        if matched_row[column] > 0:\n            assignment[matched_row[column] - 1] = column - 1\n    return assignment\n\n\ndef _global_pair_order(pairs, missions, worker_count, liquidation):\n    """Order pairs with a one-step maximum-weight public matching first."""\n    if not pairs or worker_count <= 0:\n        return sorted(pairs)\n    pair_by_worker_group = {}\n    groups_by_worker = {worker: [] for worker in range(worker_count)}\n    for pair in pairs:\n        worker = int(pair[2])\n        mission_index = int(pair[3])\n        target = pair[6]\n        group = _mission_conflict_key(\n            mission_index, missions[mission_index], target, liquidation\n        )\n        key = (worker, group)\n        incumbent = pair_by_worker_group.get(key)\n        if incumbent is None or pair < incumbent:\n            pair_by_worker_group[key] = pair\n    for (worker, group), pair in pair_by_worker_group.items():\n        groups_by_worker[worker].append((float(-pair[0]), group))\n\n    candidate_groups = set()\n    per_worker_limit = max(8, min(16, worker_count + 2))\n    for worker in range(worker_count):\n        ranked = sorted(groups_by_worker[worker], reverse=True)\n        candidate_groups.update(group for _score, group in ranked[:per_worker_limit])\n    groups = sorted(candidate_groups, key=repr)\n    group_index = {group: index for index, group in enumerate(groups)}\n    dummy_count = worker_count\n    impossible = 1e12\n    costs = [\n        [impossible] * len(groups) + [0.0] * dummy_count\n        for _ in range(worker_count)\n    ]\n    for (worker, group), pair in pair_by_worker_group.items():\n        column = group_index.get(group)\n        if column is not None:\n            costs[worker][column] = float(pair[0])\n    selected = []\n    selected_ids = set()\n    for worker, column in enumerate(_hungarian_min_cost(costs)):\n        if not (0 <= column < len(groups)):\n            continue\n        pair = pair_by_worker_group.get((worker, groups[column]))\n        if pair is None or float(-pair[0]) <= 0:\n            continue\n        selected.append(pair)\n        selected_ids.add(id(pair))\n    selected.sort(key=lambda pair: int(pair[2]))\n    selected.extend(\n        pair\n        for pair in sorted(pairs)\n        if id(pair) not in selected_ids and float(-pair[0]) > 0\n    )\n    return selected\n\n\ndef _exchange_selected_pairs(selected, pairs):\n    """Swap owners without changing the incumbent mission set."""\n    by_worker_mission = {\n        (int(pair[2]), int(pair[3])): pair\n        for pair in pairs\n    }\n    selected = list(selected)\n    for _ in range(max(1, len(selected))):\n        changed = False\n        for left in range(len(selected)):\n            for right in range(left + 1, len(selected)):\n                first = selected[left]\n                second = selected[right]\n                first_worker = int(first[2])\n                second_worker = int(second[2])\n                first_mission = int(first[3])\n                second_mission = int(second[3])\n                swapped_first = by_worker_mission.get(\n                    (second_worker, first_mission)\n                )\n                swapped_second = by_worker_mission.get(\n                    (first_worker, second_mission)\n                )\n                if swapped_first is None or swapped_second is None:\n                    continue\n                old_distance = int(first[1]) + int(second[1])\n                new_distance = (\n                    int(swapped_first[1]) + int(swapped_second[1])\n                )\n                if new_distance >= old_distance:\n                    continue\n                selected[left] = swapped_first\n                selected[right] = swapped_second\n                changed = True\n        if not changed:\n            break\n    return selected\n\n\ndef _globally_reassign_selected_pairs(selected, pairs):\n    """Minimize travel for the already selected public mission set."""\n    selected = list(selected)\n    if len(selected) <= 1:\n        return selected\n    workers = sorted(int(pair[2]) for pair in selected)\n    missions = sorted(int(pair[3]) for pair in selected)\n    by_worker_mission = {\n        (int(pair[2]), int(pair[3])): pair\n        for pair in pairs\n    }\n    impossible = 10 ** 9\n    costs = []\n    for worker in workers:\n        row = []\n        for mission in missions:\n            pair = by_worker_mission.get((worker, mission))\n            row.append(\n                impossible\n                if pair is None\n                else int(pair[1]) * 1000 + worker\n            )\n        costs.append(row)\n    assignment = _hungarian_min_cost(costs)\n    reassigned = []\n    for row, column in enumerate(assignment):\n        if not (0 <= column < len(missions)):\n            return selected\n        pair = by_worker_mission.get((workers[row], missions[column]))\n        if pair is None:\n            return selected\n        reassigned.append(pair)\n    if sum(int(pair[1]) for pair in reassigned) >= sum(\n        int(pair[1]) for pair in selected\n    ):\n        return selected\n    return reassigned\n\n\ndef _territory_owners(obs, farm, roles, positions):\n    """Assign contiguous public role zones to current workers for one day."""\n    if TERRITORY_MISMATCH_PENALTY <= 0 or not roles or not positions:\n        return {}\n    player = int((obs or {}).get("player", 0) or 0)\n    day = int((obs or {}).get("day", 0) or 0)\n    step = int((obs or {}).get("step", 0) or 0)\n    role_targets = tuple(sorted(tuple(target) for target in roles))\n    signature = (day, len(positions), role_targets)\n    cached = _TERRITORY_CERTIFICATES.get(player)\n    if (\n        cached is not None\n        and tuple(cached.get("signature", ())) == signature\n        and step > int(cached.get("step", -1))\n    ):\n        cached["step"] = step\n        return dict(cached.get("owners", {}) or {})\n\n    board_size = len(farm.get("tiles", []) or [])\n    center = ((board_size - 1) / 2.0, (board_size - 1) / 2.0)\n    ordered = sorted(\n        role_targets,\n        key=lambda target: (\n            math.atan2(target[1] - center[1], target[0] - center[0]),\n            _distance(target, center),\n            target[1],\n            target[0],\n        ),\n    )\n    worker_count = len(positions)\n    zones = [[] for _ in range(worker_count)]\n    for index, target in enumerate(ordered):\n        zone = min(worker_count - 1, index * worker_count // len(ordered))\n        zones[zone].append(target)\n    centroids = []\n    for zone in zones:\n        if not zone:\n            centroids.append(center)\n            continue\n        centroids.append((\n            sum(target[0] for target in zone) / float(len(zone)),\n            sum(target[1] for target in zone) / float(len(zone)),\n        ))\n    costs = [\n        [\n            abs(float(position[0]) - centroid[0])\n            + abs(float(position[1]) - centroid[1])\n            for centroid in centroids\n        ]\n        for position in positions\n    ]\n    assignment = _hungarian_min_cost(costs)\n    owners = {}\n    for worker, zone_index in enumerate(assignment):\n        if 0 <= zone_index < len(zones):\n            for target in zones[zone_index]:\n                owners[target] = worker\n    _TERRITORY_CERTIFICATES[player] = {\n        "signature": signature,\n        "step": step,\n        "owners": dict(owners),\n    }\n    return owners\n\n\n# Duplicate-target-aware field assignment\n\ndef _unit_actions(obs, config, farm, private, roles):\n    tiles = farm["tiles"]\n    board_size = len(tiles)\n    day = int(obs.get("day", 0) or 0)\n    hour = int(obs.get("hour", 0) or 0)\n    step = int(obs.get("step", day * 24 + hour) or 0)\n    final_step = int(_cfg(config, "episodeSteps", 720)) - 2\n    actions_left = max(0, final_step - step + 1)\n    liquidation = actions_left <= LIQUIDATION_TURNS\n\n    positions = [farm["farmer"], *(farm.get("hands", []) or [])]\n    territory_owners = _territory_owners(obs, farm, roles, positions)\n    inventories = [dict(inv or {}) for inv in private.get("inventories", []) or []]\n    while len(inventories) < len(positions):\n        inventories.append({})\n\n    summary = _survey(farm, private, roles, day)\n    jobs = _field_jobs(obs, farm, private, roles, liquidation)\n    player = int(obs.get("player", 0) or 0)\n    certificate = _TARGET_CERTIFICATES.get(player)\n    if (\n        certificate is None\n        or int(certificate.get("day", -1)) != day\n        or step <= int(certificate.get("step", -1))\n    ):\n        certificate = {"day": day, "step": step, "targets": {}}\n    sticky_targets = dict(certificate.get("targets", {}) or {})\n    momentum = _MOMENTUM_CERTIFICATES.get(player)\n    if (\n        momentum is None\n        or int(momentum.get("day", -1)) != day\n        or step <= int(momentum.get("step", -1))\n    ):\n        momentum = {"day": day, "step": step, "moves": {}}\n    previous_moves = dict(momentum.get("moves", {}) or {})\n    seed_budget = dict(private.get("seeds", {}) or {})\n    actions = [["PASS"] for _ in positions]\n\n    feed_jobs = [job for job in jobs if job["need"] == "WHEAT"]\n    shed_wheat = int((private.get("shed", {}) or {}).get("WHEAT", 0) or 0)\n    carried_wheat = sum(int(inv.get("WHEAT", 0) or 0) for inv in inventories)\n\n    missions = []\n    for job in jobs:\n        mission = dict(job)\n        mission.update({"kind": "FIELD"})\n        missions.append(mission)\n\n    wheat_missing = max(0, len(feed_jobs) - carried_wheat)\n    wheat_pickups = min(\n        len(positions),\n        int(math.ceil(min(wheat_missing, shed_wheat) / 6.0)),\n    )\n    wheat_remaining = min(wheat_missing, shed_wheat)\n    critical_feed = any(job["priority"] == 0 for job in feed_jobs)\n    for _ in range(wheat_pickups):\n        amount = min(6, wheat_remaining)\n        wheat_remaining -= amount\n        missions.append(\n            {\n                "kind": "PICKUP",\n                "item": "WHEAT",\n                "amount": amount,\n                "priority": 0 if critical_feed else 1,\n                "value": 900 if critical_feed else 500,\n                "target": None,\n            }\n        )\n\n    fertilizer_jobs = [\n        job for job in jobs if job.get("need") == "FERTILIZER"\n    ]\n    shed_fertilizer = int(\n        (private.get("shed", {}) or {}).get("FERTILIZER", 0) or 0\n    )\n    carried_fertilizer = sum(\n        int(inventory.get("FERTILIZER", 0) or 0)\n        for inventory in inventories\n    )\n    fertilizer_missing = max(\n        0, len(fertilizer_jobs) - carried_fertilizer\n    )\n    fertilizer_remaining = min(fertilizer_missing, shed_fertilizer)\n    fertilizer_pickups = min(\n        len(positions),\n        int(math.ceil(fertilizer_remaining / 4.0)),\n    )\n    for _ in range(fertilizer_pickups):\n        amount = min(4, fertilizer_remaining)\n        fertilizer_remaining -= amount\n        missions.append(\n            {\n                "kind": "PICKUP",\n                "item": "FERTILIZER",\n                "amount": amount,\n                "priority": 1,\n                "value": 700,\n                "target": None,\n            }\n        )\n\n    for animal in ANIMALS:\n        place_jobs = [job for job in jobs if job["need"] == animal]\n        shed_animals = int(\n            (private.get("shed", {}) or {}).get(animal, 0) or 0\n        )\n        carried_animals = sum(\n            int(inv.get(animal, 0) or 0) for inv in inventories\n        )\n        pickup_count = min(\n            max(0, len(place_jobs) - carried_animals),\n            shed_animals,\n            2,\n            len(positions),\n        )\n        for _ in range(pickup_count):\n            missions.append(\n                {\n                    "kind": "PICKUP",\n                    "item": animal,\n                    "amount": 1,\n                    "priority": 1,\n                    "value": 900,\n                    "target": None,\n                }\n            )\n\n    market_prices = ((obs.get("market", {}) or {}).get("prices", {}) or {})\n    pressure = summary["shed_load"] + summary["carried_load"]\n    cash_needed = (\n        day < 22\n        and float(farm.get("money", 0) or 0) < 500\n    )\n    for index, inventory in enumerate(inventories):\n        cash_units = sum(\n            max(0, int(inventory.get(item, 0) or 0)) for item in PRODUCTS\n        )\n        if cash_units <= 0:\n            continue\n        cash_value = sum(\n            max(0, int(inventory.get(item, 0) or 0))\n            * float(market_prices.get(item, MARKET[item][0]) or MARKET[item][0])\n            for item in PRODUCTS\n        )\n        has_feed_mission = (\n            int(inventory.get("WHEAT", 0) or 0) > 0 and bool(feed_jobs)\n        )\n        should_drop = (\n            liquidation\n            or pressure >= DROP_PRESSURE_THRESHOLD\n            or cash_units >= DROP_UNIT_THRESHOLD\n            or cash_value >= DROP_VALUE_THRESHOLD\n            or (cash_needed and cash_value >= CASH_DROP_VALUE_THRESHOLD)\n            or (\n                tuple(positions[index]) in _shed_tiles(board_size, tiles)\n                and not has_feed_mission\n                and cash_needed\n            )\n        )\n        if should_drop:\n            missions.append(\n                {\n                    "kind": "DROP",\n                    "eligible": index,\n                    "priority": -1 if liquidation else 2,\n                    "value": max(120.0, 0.22 * cash_value),\n                    "target": None,\n                }\n            )\n\n    pairs = []\n    for worker_index, raw_position in enumerate(positions):\n        position = (int(raw_position[0]), int(raw_position[1]))\n        inventory = inventories[worker_index]\n        for mission_index, mission in enumerate(missions):\n            kind = mission["kind"]\n            if kind == "DROP" and mission["eligible"] != worker_index:\n                continue\n            if kind == "FIELD":\n                need = mission.get("need")\n                if need is not None and int(inventory.get(need, 0) or 0) <= 0:\n                    continue\n                target = mission["target"]\n                distance = _distance(position, target)\n                if hour + distance > mission.get("latest_hour", 23):\n                    continue\n                if liquidation and not _terminal_feasible(\n                    position, target, tiles, actions_left\n                ):\n                    continue\n            else:\n                target = _nearest_shed(position, board_size, tiles)\n                distance = _distance(position, target)\n                if kind == "PICKUP" and int(\n                    inventory.get(mission["item"], 0) or 0\n                ) > 0:\n                    continue\n\n            priority = int(mission["priority"])\n            cross_cost = 0.0\n            if (\n                mission["kind"] == "FIELD"\n                and _quadrant_of(position, board_size)\n                != _quadrant_of(target, board_size)\n            ):\n                cross_cost = QUADRANT_CROSS_COST\n                if priority >= 2:\n                    cross_cost += OPTIONAL_QUADRANT_CROSS_COST\n            score = (\n                PRIORITY_BONUS.get(priority, -1000.0 * priority)\n                + float(mission["value"])\n                - TRAVEL_COST * distance\n                - cross_cost\n            )\n            if (\n                TARGET_STICKINESS_BONUS > 0\n                and mission["kind"] == "FIELD"\n                and tuple(target)\n                == tuple(sticky_targets.get(worker_index, (-1, -1)))\n            ):\n                score += float(TARGET_STICKINESS_BONUS)\n            if (\n                SAME_TILE_COMPLETION_BONUS > 0\n                and mission["kind"] == "FIELD"\n                and distance == 0\n                and priority > 0\n                and tuple(target)\n                == tuple(sticky_targets.get(worker_index, (-1, -1)))\n            ):\n                score += float(SAME_TILE_COMPLETION_BONUS)\n            if (\n                MOVE_REVERSAL_PENALTY > 0\n                and distance > 0\n                and priority > 0\n            ):\n                next_step = _bfs_first_step(\n                    tiles, positions[worker_index], target\n                )\n                previous = previous_moves.get(worker_index)\n                if (\n                    next_step\n                    and next_step[0] == _OPPOSITE_MOVE.get(previous)\n                ):\n                    score -= float(MOVE_REVERSAL_PENALTY)\n            if (\n                TERRITORY_MISMATCH_PENALTY > 0\n                and mission["kind"] == "FIELD"\n                and priority > 0\n                and territory_owners.get(tuple(target), worker_index)\n                != worker_index\n            ):\n                score -= float(TERRITORY_MISMATCH_PENALTY)\n            pairs.append(\n                (\n                    -score,\n                    distance,\n                    worker_index,\n                    mission_index,\n                    target[1],\n                    target[0],\n                    target,\n                )\n            )\n\n    used_workers = set()\n    used_missions = set()\n    used_targets = set()\n    selected_targets = {}\n    selected_field_pairs = []\n    shed_capacity = int(_cfg(config, "shedCapacity", SHED_CAPACITY))\n    drop_room = max(0, shed_capacity - summary["shed_load"])\n    pair_order = (\n        _global_pair_order(pairs, missions, len(positions), liquidation)\n        if GLOBAL_PAIR_MATCHING\n        else sorted(pairs)\n    )\n    for pair in pair_order:\n        _, distance, worker_index, mission_index, _, _, target = pair\n        if worker_index in used_workers or mission_index in used_missions:\n            continue\n        mission = missions[mission_index]\n        target_key = target\n        if mission["kind"] == "FIELD":\n            operation = mission["action"][0]\n            if (\n                liquidation\n                and operation in {"HARVEST", "COLLECT_FERTILIZER"}\n            ) or operation == "FERTILIZE":\n                target_key = (target, operation)\n            if target_key in used_targets:\n                continue\n\n        action = None\n        plant_crop = None\n        if mission["kind"] == "FIELD":\n            planned = mission["action"]\n            if planned[0] == "PLANT":\n                plant_crop = planned[1]\n                if int(seed_budget.get(plant_crop, 0) or 0) <= 0:\n                    continue\n            action = (\n                list(planned)\n                if distance == 0\n                else _bfs_first_step(tiles, positions[worker_index], target)\n            )\n        elif mission["kind"] == "PICKUP":\n            action = (\n                ["PICKUP", mission["item"], int(mission["amount"])]\n                if distance == 0\n                else _bfs_first_step(tiles, positions[worker_index], target)\n            )\n        else:\n            inventory = inventories[worker_index]\n            product_counts = {\n                item: max(0, int(inventory.get(item, 0) or 0))\n                for item in PRODUCTS\n                if int(inventory.get(item, 0) or 0) > 0\n            }\n            if distance:\n                action = _bfs_first_step(\n                    tiles, positions[worker_index], target\n                )\n            else:\n                cash_units = sum(product_counts.values())\n                noncash = _inventory_total(inventory) - cash_units\n                if cash_units <= 0 or drop_room <= 0:\n                    continue\n                if noncash <= 0 and cash_units <= drop_room:\n                    action = ["DROP"]\n                    drop_room -= cash_units\n                else:\n                    item = max(\n                        product_counts,\n                        key=lambda name: (\n                            float(\n                                market_prices.get(name, MARKET[name][0])\n                                or MARKET[name][0]\n                            ),\n                            name,\n                        ),\n                    )\n                    quantity = min(product_counts[item], drop_room)\n                    if quantity <= 0:\n                        continue\n                    action = ["PLACE", item, quantity]\n                    drop_room -= quantity\n\n        if not action or (action == ["PASS"] and distance > 0):\n            continue\n        if plant_crop is not None:\n            seed_budget[plant_crop] -= 1\n        if mission["kind"] == "FIELD":\n            used_targets.add(target_key)\n            selected_targets[worker_index] = tuple(target)\n            selected_field_pairs.append(pair)\n        actions[worker_index] = action\n        used_workers.add(worker_index)\n        used_missions.add(mission_index)\n\n    if (\n        MISSION_PRESERVING_EXCHANGE\n        or MISSION_PRESERVING_GLOBAL_ASSIGNMENT\n    ) and len(selected_field_pairs) > 1:\n        field_pairs = [\n            pair for pair in pairs\n            if missions[int(pair[3])]["kind"] == "FIELD"\n        ]\n        selected_field_pairs = (\n            _globally_reassign_selected_pairs(\n                selected_field_pairs, field_pairs\n            )\n            if MISSION_PRESERVING_GLOBAL_ASSIGNMENT\n            else _exchange_selected_pairs(selected_field_pairs, field_pairs)\n        )\n        selected_targets = {}\n        for pair in selected_field_pairs:\n            _, distance, worker_index, mission_index, _, _, target = pair\n            planned = missions[mission_index]["action"]\n            actions[worker_index] = (\n                list(planned)\n                if distance == 0\n                else _bfs_first_step(\n                    tiles, positions[worker_index], target\n                )\n            )\n            selected_targets[worker_index] = tuple(target)\n\n    if TARGET_STICKINESS_BONUS > 0 or SAME_TILE_COMPLETION_BONUS > 0:\n        live_targets = {\n            tuple(mission["target"])\n            for mission in missions\n            if mission["kind"] == "FIELD"\n        }\n        retained = {\n            int(worker_index): tuple(target)\n            for worker_index, target in sticky_targets.items()\n            if int(worker_index) < len(positions)\n            and tuple(target) in live_targets\n        }\n        claimed = set(selected_targets.values())\n        retained = {\n            worker_index: target\n            for worker_index, target in retained.items()\n            if target not in claimed or selected_targets.get(worker_index) == target\n        }\n        retained.update(selected_targets)\n        _TARGET_CERTIFICATES[player] = {\n            "day": day,\n            "step": step,\n            "targets": retained,\n        }\n    if MOVE_REVERSAL_PENALTY > 0:\n        _MOMENTUM_CERTIFICATES[player] = {\n            "day": day,\n            "step": step,\n            "moves": {\n                index: action[0]\n                for index, action in enumerate(actions)\n                if action and action[0] in _OPPOSITE_MOVE\n            },\n        }\n\n    return {\n        "farmer": actions[0] if actions else ["PASS"],\n        "hands": actions[1:],\n        "liquidation": liquidation,\n    }\n\n\n# Market and capital allocation\n\ndef _fib(index):\n    a, b = 1, 1\n    for _ in range(index):\n        a, b = b, a + b\n    return a\n\n\ndef _sale_cash_credit(proceeds):\n    """Cash available to later orders after an earlier sale in the queue."""\n    return max(0.0, float(proceeds)) * float(SALE_CASH_FACTOR)\n\n\ndef _release_committed_sale_cash(money, gross_sale_proceeds):\n    """Release any extra engine-backed sale cash to seeds and crew only."""\n    extra_factor = max(\n        0.0,\n        float(COMMITTED_WORK_SALE_CASH_FACTOR) - float(SALE_CASH_FACTOR),\n    )\n    return float(money) + extra_factor * max(0.0, float(gross_sale_proceeds))\n\n\ndef _pending_drop(private, field, capacity=SHED_CAPACITY):\n    pending = {}\n    inventories = list(private.get("inventories", []) or [])\n    actions = [field["farmer"], *field["hands"]]\n    room = max(\n        0,\n        int(capacity)\n        - sum(\n            max(0, int(value or 0))\n            for value in (private.get("shed", {}) or {}).values()\n        ),\n    )\n    for index, action in enumerate(actions):\n        if index >= len(inventories) or not action or room <= 0:\n            continue\n        inventory = inventories[index] or {}\n        if action[0] == "DROP":\n            for item, count in inventory.items():\n                accepted = min(max(0, int(count or 0)), room)\n                if item in PRODUCTS and accepted > 0:\n                    pending[item] = pending.get(item, 0) + accepted\n                room -= accepted\n                if room <= 0:\n                    break\n        elif action[0] == "PLACE" and len(action) >= 2:\n            item = action[1]\n            requested = int(action[2]) if len(action) >= 3 else 1\n            accepted = min(\n                max(0, requested),\n                max(0, int(inventory.get(item, 0) or 0)),\n                room,\n            )\n            if item in PRODUCTS and accepted > 0:\n                pending[item] = pending.get(item, 0) + accepted\n            room -= accepted\n    return pending\n\n\ndef _post_field_storage(private, field, capacity=SHED_CAPACITY):\n    shed = {\n        item: max(0, int(count or 0))\n        for item, count in (private.get("shed", {}) or {}).items()\n    }\n    inventories = [\n        {\n            item: max(0, int(count or 0))\n            for item, count in (inventory or {}).items()\n            if int(count or 0) > 0\n        }\n        for inventory in (private.get("inventories", []) or [])\n    ]\n    actions = [field.get("farmer", ["PASS"]), *field.get("hands", [])]\n\n    while len(inventories) < len(actions):\n        inventories.append({})\n\n    for index, action in enumerate(actions):\n        if not action:\n            continue\n        inventory = inventories[index]\n        operation = action[0]\n        if operation == "DROP":\n            for item, count in list(inventory.items()):\n                room = max(0, int(capacity) - sum(shed.values()))\n                accepted = min(max(0, int(count or 0)), room)\n                if accepted > 0:\n                    shed[item] = shed.get(item, 0) + accepted\n                del inventory[item]\n        elif operation == "PLACE" and len(action) >= 2:\n            item = action[1]\n            if item not in PRODUCTS:\n                continue\n            requested = int(action[2]) if len(action) >= 3 else 1\n            accepted = min(\n                max(0, requested),\n                max(0, int(inventory.get(item, 0) or 0)),\n                max(0, int(capacity) - sum(shed.values())),\n            )\n            if accepted > 0:\n                inventory[item] -= accepted\n                if inventory[item] == 0:\n                    del inventory[item]\n                shed[item] = shed.get(item, 0) + accepted\n        elif operation == "PICKUP" and len(action) >= 2:\n            item = action[1]\n            requested = int(action[2]) if len(action) >= 3 else 1\n            picked = min(\n                max(0, requested),\n                max(0, int(shed.get(item, 0) or 0)),\n            )\n            if picked > 0:\n                shed[item] -= picked\n                inventory[item] = inventory.get(item, 0) + picked\n        elif (\n            operation == "FEED"\n            and int(inventory.get("WHEAT", 0) or 0) > 0\n        ):\n            inventory["WHEAT"] -= 1\n            if inventory["WHEAT"] == 0:\n                del inventory["WHEAT"]\n        elif (\n            operation == "FERTILIZE"\n            and int(inventory.get("FERTILIZER", 0) or 0) > 0\n        ):\n            inventory["FERTILIZER"] -= 1\n            if inventory["FERTILIZER"] == 0:\n                del inventory["FERTILIZER"]\n\n    return shed, inventories\n\n\ndef _sell_quantity(item, have, inventory, day, shed_load, obs=None):\n    left = TOTAL_DAYS - day\n    if left <= 1:\n        return have\n    base = _market_parameters(obs, item)[0]\n    reserve = base * RESERVE_FRACTION[item]\n    if left <= 7:\n        reserve *= max(0.0, (left - 1) / 6.0)\n    if shed_load >= 0.75:\n        reserve *= 0.55\n\n    opponent_supply = _opponent_visible_supply(obs, item, horizon=1)\n    town_demand = _town_demand_per_day(obs, item)\n    if opponent_supply > town_demand:\n        reserve *= max(0.72, 1.0 - 0.015 * (opponent_supply - town_demand))\n    projected_inventory = inventory + opponent_supply - town_demand\n    future_price = _price_at(item, projected_inventory, obs)\n    threshold = reserve\n    if shed_load < 0.75 and left > 7:\n        threshold = max(threshold, 0.88 * future_price)\n\n    quantity = 0\n    while (\n        quantity < have\n        and _price_at(item, inventory + quantity, obs) >= threshold\n    ):\n        quantity += 1\n    if left <= 12:\n        forced = int(math.ceil(have / float(max(1, left - 1))))\n        quantity = max(quantity, min(have, forced))\n    return quantity\n\n\ndef _seed_needs(obs, farm, private, roles):\n    day = int(obs.get("day", 0) or 0)\n    seeds = private.get("seeds", {}) or {}\n    needs = {}\n    for (x, y), (kind, item) in roles.items():\n        if (\n            kind == "CROP"\n            and (\n                farm["tiles"][y][x] is None\n                or (\n                    isinstance(farm["tiles"][y][x], dict)\n                    and farm["tiles"][y][x].get("kind") == "WEED"\n                )\n            )\n            and day <= CROPS[item]["last_plant"]\n        ):\n            needs[item] = needs.get(item, 0) + 1\n    return {\n        crop: max(0, count - int(seeds.get(crop, 0) or 0))\n        for crop, count in needs.items()\n    }\n\n\ndef _target_hands(obs, farm, private, roles):\n    day = int(obs.get("day", 0) or 0)\n    summary = _survey(farm, private, roles, day)\n    due_jobs = len(_field_jobs(obs, farm, private, roles, liquidation=False))\n    active_roles = (\n        summary["plants"]\n        + summary["animals"]\n        + summary["plantable"]\n        + summary["structures_todo"]\n    )\n    floor = 10 if day <= 27 and active_roles > 0 else 4\n    risk_load = 2 * (\n        summary["at_risk_animals"] + summary["at_risk_crops"]\n    )\n    demand_target = int(math.ceil((due_jobs + risk_load) / 7.0))\n    return max(4, min(MAX_HANDS, max(floor, demand_target)))\n\n\ndef _market_actions(obs, config, farm, private, roles, field):\n    day = int(obs.get("day", 0) or 0)\n    hour = int(obs.get("hour", 0) or 0)\n    left = TOTAL_DAYS - day\n    money = float(farm.get("money", 0) or 0)\n    shed_capacity = int(_cfg(config, "shedCapacity", SHED_CAPACITY))\n    shed, post_field_inventories = _post_field_storage(\n        private, field, shed_capacity\n    )\n    market_inventory = dict(\n        ((obs.get("market", {}) or {}).get("inventory", {}) or {})\n    )\n    max_orders = int(_cfg(config, "maxMarketOrdersPerTurn", MAX_MARKET_ORDERS))\n    summary = _survey(farm, private, roles, day)\n    phase = _policy_phase(obs, farm, private, summary)\n    orders = []\n    gross_sale_proceeds = 0.0\n    occupancy = sum(max(0, int(value or 0)) for value in shed.values())\n    shed_load = occupancy / float(max(1, shed_capacity))\n    animal_pipeline = summary["animals"] + sum(\n        summary["animal_stock"].values()\n    )\n    feed_floor = animal_pipeline * FEED_STOCK_DAYS\n    total_wheat = int(shed.get("WHEAT", 0) or 0) + sum(\n        int(inventory.get("WHEAT", 0) or 0)\n        for inventory in post_field_inventories\n    )\n\n    sells = []\n    for item in PRODUCTS:\n        have = int(shed.get(item, 0) or 0)\n        if item == "WHEAT" and left > 2:\n            have = min(have, max(0, total_wheat - feed_floor))\n        if have <= 0:\n            continue\n        raw_inventory = market_inventory.get(item)\n        inventory = MARKET_I0 if raw_inventory is None else int(raw_inventory)\n        quantity = _sell_quantity(\n            item, have, inventory, day, shed_load, obs\n        )\n        if quantity <= 0:\n            continue\n        proceeds = sum(\n            _price_at(item, inventory + offset, obs)\n            for offset in range(quantity)\n        )\n        sells.append((proceeds, item, quantity))\n    sells.sort(reverse=True)\n    for proceeds, item, quantity in sells:\n        if len(orders) >= max_orders:\n            break\n        orders.append(["SELL", item, quantity])\n        money += _sale_cash_credit(proceeds)\n        gross_sale_proceeds += proceeds\n        occupancy = max(0, occupancy - quantity)\n        shed[item] = max(0, int(shed.get(item, 0) or 0) - quantity)\n        raw_inventory = market_inventory.get(item)\n        inventory = MARKET_I0 if raw_inventory is None else int(raw_inventory)\n        market_inventory[item] = inventory + quantity\n\n    if field["liquidation"] or left <= 1:\n        if day >= 29 and hour <= 1:\n            terminal_jobs = _field_jobs(\n                obs, farm, private, roles, liquidation=True\n            )\n            target = min(8, len(terminal_jobs))\n            hires = int(farm.get("hires_today", 0) or 0)\n            while hires < target and len(orders) < max_orders:\n                cost = _fib(hires)\n                if money < cost + 20:\n                    break\n                orders.append(["HIRE"])\n                money -= cost\n                hires += 1\n        return orders[:max_orders]\n\n    placed = _farm_animal_counts(farm)\n    role_targets = {animal: 0 for animal in ANIMALS}\n    for kind, item in roles.values():\n        if kind == "ANIMAL" and item in role_targets:\n            role_targets[item] += 1\n    owned = {\n        animal: placed[animal] + _private_item_total(private, animal)\n        for animal in ANIMALS\n    }\n    animal_capital_open = phase in {"BOOTSTRAP", "COMPOUND"} or (\n        phase == "CRISIS"\n        and summary["at_risk_animals"] == 0\n        and summary["shed_load"] + summary["carried_load"] < 95\n        and summary["open_structures"] > 0\n        and animal_pipeline\n        < summary["animals"] + summary["open_structures"]\n    )\n    if (\n        animal_capital_open\n        and day <= ANIMAL_PURCHASE_LAST_DAY\n        and left >= 8\n    ):\n        purchase_order = sorted(\n            LIVESTOCK_TYPES,\n            key=lambda animal: (\n                _livestock_score(\n                    obs,\n                    animal,\n                    owned[animal],\n                    _opponent_animal_counts(obs)[animal],\n                ),\n                role_targets[animal] - owned[animal],\n                animal == "COW",\n            ),\n            reverse=True,\n        )\n        for animal in purchase_order:\n            if len(orders) >= max_orders:\n                break\n            missing = max(0, role_targets[animal] - owned[animal])\n            if missing <= 0:\n                continue\n            operating_reserve = 80 if sum(owned.values()) < CORE_HERD else 220\n            quantity = min(\n                missing,\n                2,\n                max(0, shed_capacity - occupancy),\n                max(\n                    0,\n                    int(\n                        (money - operating_reserve)\n                        // ANIMALS[animal]["cost"]\n                    ),\n                ),\n            )\n            if quantity > 0:\n                orders.append(["BUY_ANIMAL", animal, quantity])\n                money -= quantity * ANIMALS[animal]["cost"]\n                occupancy += quantity\n                owned[animal] += quantity\n\n    total_wheat = int(shed.get("WHEAT", 0) or 0) + sum(\n        int(inventory.get("WHEAT", 0) or 0)\n        for inventory in post_field_inventories\n    )\n    planned_herd = sum(owned.values())\n    desired_wheat = max(\n        planned_herd * FEED_STOCK_DAYS,\n        8 if planned_herd > 0 else 0,\n    )\n    if (\n        desired_wheat > total_wheat\n        and len(orders) < max_orders\n        and planned_herd > 0\n    ):\n        raw_inventory = market_inventory.get("WHEAT")\n        inventory = MARKET_I0 if raw_inventory is None else int(raw_inventory)\n        emergency_reserve = 0 if summary["at_risk_animals"] else 80\n        quantity = 0\n        cost = 0\n        limit = min(\n            desired_wheat - total_wheat,\n            max(0, shed_capacity - occupancy),\n        )\n        for offset in range(limit):\n            unit = _price_at("WHEAT", inventory - offset - 1, obs)\n            if money - cost - unit < emergency_reserve:\n                break\n            cost += unit\n            quantity += 1\n        if quantity > 0:\n            orders.append(["BUY_PRODUCT", "WHEAT", quantity])\n            money -= cost\n            occupancy += quantity\n\n    extra_land = max(0, len(farm.get("unlocked_quadrants", ["NW"])) - 1)\n    if (\n        phase in {"BOOTSTRAP", "COMPOUND"}\n        and extra_land < MAX_EXTRA_LAND\n        and day >= LAND_OPEN_DAYS[extra_land]\n        and left >= 12\n        and len(orders) < max_orders\n    ):\n        cost = LAND_PRICES[extra_land]\n        reserve = 300 if extra_land == 0 else 500\n        if money >= cost + reserve:\n            orders.append(["BUY_LAND"])\n            money -= cost\n\n    # Animal, feed and land choices keep the conservative base cash buffer.\n    # Only after those choices are fixed may named seed/crew obligations use\n    # the remainder of the exact engine sale credit.\n    money = _release_committed_sale_cash(money, gross_sale_proceeds)\n    needs = _seed_needs(obs, farm, private, roles)\n    seed_reserve = 80 if day <= 4 else 150\n    seed_order = (\n        ("MELON",)\n        if day == 0\n        else ("MELON", "WHEAT", "STRAWBERRY", "CARROT", "TOMATO")\n    )\n    for crop in seed_order:\n        if len(orders) >= max_orders or needs.get(crop, 0) <= 0:\n            continue\n        cost = CROPS[crop]["seed"]\n        quantity = min(\n            needs[crop],\n            25,\n            max(0, int((money - seed_reserve) // cost)),\n        )\n        if quantity > 0:\n            orders.append(["BUY_SEED", crop, quantity])\n            money -= quantity * cost\n\n    if hour <= 2:\n        target_hands = _target_hands(obs, farm, private, roles)\n        hires = int(farm.get("hires_today", 0) or 0)\n        while hires < target_hands and len(orders) < max_orders:\n            cost = _fib(hires)\n            if money < max(20, 3 * cost):\n                break\n            orders.append(["HIRE"])\n            money -= cost\n            hires += 1\n\n    return orders[:max_orders]\n\n\ndef _decide(obs, config=None):\n    farms = obs.get("farms", []) or []\n    player = int(obs.get("player", 0) or 0)\n    if not (0 <= player < len(farms)):\n        return {"farmer": ["PASS"], "hands": [], "market": []}\n    farm = farms[player]\n    private = obs.get("private", {}) or {}\n    roles = _role_plan(obs, farm)\n    field = _unit_actions(obs, config, farm, private, roles)\n    return {\n        "farmer": field["farmer"],\n        "hands": field["hands"],\n        "market": _market_actions(obs, config, farm, private, roles, field),\n    }\n\n\ndef agent(obs, config=None):\n    try:\n        return _decide(obs, config)\n    except Exception:\n        farms = obs.get("farms", []) if hasattr(obs, "get") else []\n        player = int(obs.get("player", 0)) if hasattr(obs, "get") else 0\n        hand_count = (\n            len(farms[player].get("hands", []) or [])\n            if 0 <= player < len(farms)\n            else 0\n        )\n        return {\n            "farmer": ["PASS"],\n            "hands": [["PASS"] for _ in range(hand_count)],\n            "market": [],\n        }\n\n\ndef whitebox_v239_public_scenario_c06(obs):\n    """Packaged entry for the audited public-state C06 policy."""\n    return agent(obs)\n'
_BUNDLE_SOURCES['whitebox.versions.v250_public_scenario_sale60'] = '"""V250: audited C06 public-state policy with 60% sale reserve.\n\nThe only change from V239 is a live market rule: retain 60% of the C06\nper-item reserve fraction before the final liquidation window.  This is\ncomputed from current public market prices, town demand, shed load, and the\nvisible opponent supply; it is not an opponent-specific schedule.\n"""\nfrom whitebox.versions import v239_public_scenario_c06 as _c06\n\n_c06.RESERVE_FRACTION = {\n    item: float(value) * 0.60\n    for item, value in _c06.RESERVE_FRACTION.items()\n}\n\n\ndef whitebox_v250_public_scenario_sale60(obs):\n    return _c06.agent(obs)\n\n'
_BUNDLE_SOURCES['whitebox.versions.v278_public_rate_12_herd'] = '"""V278 diagnostic: public production frequency tilt at twelve percent."""\nfrom whitebox.versions import v250_public_scenario_sale60 as _v250\n_c06 = _v250._c06\n_base_score = _c06._livestock_score\ndef _livestock_score(obs, animal, own_count, opponent_count):\n    score = _base_score(obs, animal, own_count, opponent_count)\n    interval = max(1, int(_c06.ANIMALS[animal].get("interval", 1)))\n    return score * (1.0 + 0.12 * (2.0 / float(interval) - 1.0))\n_c06._livestock_score = _livestock_score\ndef whitebox_v278_public_rate_12_herd(obs):\n    return _c06.agent(obs)\n'
_BUNDLE_SOURCES['whitebox.versions.v305_public_rate12_fert6'] = '"""V305 candidate: V278 production-rate tilt plus a six-unit fertilizer\nreserve, preventing free byproduct from displacing productive stock."""\nfrom whitebox.versions import v278_public_rate_12_herd as _v278\n\n_c06 = _v278._c06\n_base_sell = _c06._sell_quantity\n\n\ndef _sell_quantity(item, have, inventory, day, shed_load, obs=None):\n    quantity = _base_sell(item, have, inventory, day, shed_load, obs)\n    if item == "FERTILIZER" and have > 6 and day < _c06.TOTAL_DAYS - 1:\n        quantity = max(quantity, have - 6)\n    return min(have, quantity)\n\n\n_c06._sell_quantity = _sell_quantity\n\n\ndef whitebox_v305_public_rate12_fert6(obs):\n    return _c06.agent(obs)\n'
_BUNDLE_SOURCES['whitebox.versions.v318_public_wheat_certificate3'] = '"""V318: retain the full three-day feed certificate on day 28.\n\nV308 retained two days but the base market routine still computed a\nthree-day purchase target, so it could sell 15 wheat and immediately buy 15.\nThe reserve is now exactly the same certificate used by the purchase branch,\nwhich makes the day-28 transaction set idempotent.  Day 29 terminal\nliquidation sells the certificate normally.\n"""\n\nfrom whitebox.versions import v305_public_rate12_fert6 as _v305\n\n_c06 = _v305._c06\n_base_sell_quantity = _c06._sell_quantity\n\n\ndef _farm_animals(obs):\n    player = int((obs or {}).get("player", 0) or 0)\n    farms = (obs or {}).get("farms", []) or []\n    if not (0 <= player < len(farms)):\n        return 0\n    return sum(\n        1\n        for row in farms[player].get("tiles", []) or []\n        for tile in row or ()\n        if isinstance(tile, dict) and tile.get("animal") in _c06.ANIMALS\n    )\n\n\ndef _sell_quantity(item, have, inventory, day, shed_load, obs=None):\n    quantity = _base_sell_quantity(item, have, inventory, day, shed_load, obs)\n    if item == "WHEAT" and int(day) == _c06.TOTAL_DAYS - 2:\n        reserve = _farm_animals(obs) * int(_c06.FEED_STOCK_DAYS)\n        quantity = min(quantity, max(0, int(have) - reserve))\n    return min(int(have), max(0, int(quantity)))\n\n\n_c06._sell_quantity = _sell_quantity\n\n\ndef whitebox_v318_public_wheat_certificate3(obs):\n    return _c06.agent(obs)\n'
_BUNDLE_SOURCES['whitebox.versions.v336_public_care_value25'] = '"""V336: retain CARE\'s original priority, but price its multiplier at 2.5x."""\nfrom whitebox.versions import v318_public_wheat_certificate3 as _v318\n_c06 = _v318._c06\n_base_jobs = _c06._field_jobs\ndef _field_jobs(obs, farm, private, roles, liquidation):\n    jobs = _base_jobs(obs, farm, private, roles, liquidation)\n    if not liquidation:\n        prices = ((obs or {}).get("market", {}) or {}).get("prices", {}) or {}\n        for job in jobs:\n            if job.get("reason") != "care": continue\n            t = job.get("target", (0, 0)); tile = farm.get("tiles", [])[int(t[1])][int(t[0])]\n            animal = tile.get("animal") if isinstance(tile, dict) else None; rule = _c06.ANIMALS.get(animal)\n            if rule:\n                p = float(prices.get(rule["product"], _c06.MARKET[rule["product"]][0]) or _c06.MARKET[rule["product"]][0])\n                job["value"] = max(float(job.get("value", 0)), 2.5 * p)\n    return jobs\n_c06._field_jobs = _field_jobs\ndef whitebox_v336_public_care_value25(obs): return _c06.agent(obs)\n'
_BUNDLE_SOURCES['whitebox.versions.v350_public_conditional_weed'] = '"""V350: service a severe visible weed backlog before it blocks crops.\n\nWeed clearing stays at the base priority for ordinary noise.  Once the live\nfarm has a large backlog, clearing jobs receive a limited priority bump while\nthere is still time to plant; this uses no opponent identity or schedule.\n"""\n\nfrom whitebox.versions import v336_public_care_value25 as _v336\n\n_c06 = _v336._c06\n_base_jobs = _c06._field_jobs\n\n\ndef _field_jobs(obs, farm, private, roles, liquidation):\n    jobs = _base_jobs(obs, farm, private, roles, liquidation)\n    if liquidation:\n        return jobs\n    day = int((obs or {}).get("day", 0) or 0)\n    weeds = sum(\n        1\n        for row in farm.get("tiles", []) or []\n        for tile in row or ()\n        if isinstance(tile, dict) and tile.get("kind") == "WEED"\n    )\n    if weeds < 9 or day > 21:\n        return jobs\n    # At this threshold the backlog itself is the evidence of lost land.\n    # Priority 3 remains below feeding/watering/harvest, but outranks normal\n    # planting and routine care.\n    for job in jobs:\n        if job.get("reason") == "dig_weed":\n            job["priority"] = min(int(job.get("priority", 4)), 3)\n            job["value"] = max(float(job.get("value", 0)), 160.0)\n    return jobs\n\n\n_c06._field_jobs = _field_jobs\n\n\ndef whitebox_v350_public_conditional_weed(obs):\n    return _c06.agent(obs)\n'
_BUNDLE_SOURCES['whitebox.versions.v361_public_wheat_rotation22'] = '"""V361: reserve twenty-two crop slots for repeatable wheat rotation."""\nfrom whitebox.versions import v350_public_conditional_weed as _v350\n_c06 = _v350._c06\n_c06.CROP_MIX = {\n    "NW": {"MELON": 10, "WHEAT": 6, "CARROT": 2},\n    "NE": {"WHEAT": 8, "CARROT": 1},\n    "SW": {"WHEAT": 8, "CARROT": 1},\n    "SE": {"WHEAT": 8, "CARROT": 2},\n}\ndef whitebox_v361_public_wheat_rotation22(obs): return _c06.agent(obs)\n'
_BUNDLE_SOURCES['whitebox.versions.v384_public_daily_route_certificate'] = '"""V384: retain a live, public-state route certificate for each farm day.\n\nThe C06 policy already chooses useful field jobs, but historically rematched\nevery worker to every job after every observation.  This version changes only\nexecution: public jobs are packed into multi-stop day routes, retained across\nturns, and revalidated against the live tile state before every emitted action.\nNo opponent identity, replay, fitted schedule, or hidden state is retained.\n"""\n\nfrom route import router\nfrom whitebox.versions import v361_public_wheat_rotation22 as _v361\n\n\n_c06 = _v361._c06\n_ROUTE_CERTIFICATES = {}\n\n_OP_ORDER = {\n    "FEED": 0,\n    "FERTILIZE": 1,\n    "WATER": 2,\n    "CARE": 3,\n    "HARVEST": 4,\n    "COLLECT_FERTILIZER": 5,\n    "DIG": 6,\n    "BUILD_COOP": 7,\n    "BUILD_PASTURE": 7,\n    "PLACE": 8,\n    "PLANT": 9,\n}\n\n\ndef reset(seat=None):\n    if seat is None:\n        _ROUTE_CERTIFICATES.clear()\n    else:\n        _ROUTE_CERTIFICATES.pop(int(seat), None)\n\n\ndef _action_key(action):\n    return tuple(action or ("PASS",))\n\n\ndef _job_key(job):\n    return tuple(job["target"]), _action_key(job["action"])\n\n\ndef _need_for(action):\n    operation = action[0] if action else "PASS"\n    if operation == "FEED":\n        return "WHEAT"\n    if operation == "FERTILIZE":\n        return "FERTILIZER"\n    if operation == "PLACE" and len(action) >= 2 and action[1] in _c06.ANIMALS:\n        return action[1]\n    return None\n\n\ndef _all_shed_tiles(board_size):\n    half = int(board_size) // 2\n    return (\n        (half - 1, half - 1),\n        (half, half - 1),\n        (half - 1, half),\n        (half, half),\n    )\n\n\ndef _nearest_shed(position, board_size):\n    return min(\n        _all_shed_tiles(board_size),\n        key=lambda target: (_c06._distance(position, target), target[1], target[0]),\n    )\n\n\ndef _step_toward(position, target):\n    """One legal Manhattan step; locked tiles are publicly known passable."""\n    x, y = int(position[0]), int(position[1])\n    tx, ty = int(target[0]), int(target[1])\n    if y < ty:\n        return ["SOUTH"]\n    if y > ty:\n        return ["NORTH"]\n    if x < tx:\n        return ["EAST"]\n    if x > tx:\n        return ["WEST"]\n    return ["PASS"]\n\n\ndef _live_jobs(obs, farm, private, roles, liquidation):\n    hour = int(obs.get("hour", 0) or 0)\n    return [\n        job for job in _c06._field_jobs(obs, farm, private, roles, liquidation)\n        if hour <= int(job.get("latest_hour", 23) or 23)\n    ]\n\n\ndef _task_groups(jobs):\n    grouped = {}\n    for job in jobs:\n        grouped.setdefault(tuple(job["target"]), []).append(job)\n\n    tasks = []\n    for target, target_jobs in sorted(grouped.items()):\n        unique = {}\n        for job in target_jobs:\n            key = _action_key(job["action"])\n            incumbent = unique.get(key)\n            if incumbent is None or (\n                int(job["priority"]), -float(job["value"])\n            ) < (\n                int(incumbent["priority"]), -float(incumbent["value"])\n            ):\n                unique[key] = job\n        ordered = sorted(\n            unique.values(),\n            key=lambda job: (\n                _OP_ORDER.get(job["action"][0], 50),\n                int(job["priority"]),\n                _action_key(job["action"]),\n            ),\n        )\n        carry = {}\n        for job in ordered:\n            need = job.get("need") or _need_for(job["action"])\n            if need is not None:\n                carry[need] = carry.get(need, 0) + 1\n        priority = min(int(job["priority"]) for job in ordered)\n        value = sum(\n            max(1.0, float(job["value"]))\n            + float(_c06.PRIORITY_BONUS.get(int(job["priority"]), 0.0))\n            for job in ordered\n        )\n        tasks.append(\n            router.Task(\n                target,\n                [list(job["action"]) for job in ordered],\n                carry=carry,\n                value=value,\n                mandatory=priority <= 0,\n                kind="PUBLIC_ROUTE_" + "+".join(\n                    str(job.get("reason") or job["action"][0])\n                    for job in ordered\n                ),\n            )\n        )\n    return tasks\n\n\ndef _service_job(job):\n    reason = str(job.get("reason", ""))\n    operation = str((job.get("action") or ["PASS"])[0])\n    return (\n        reason.startswith(("build_", "place_"))\n        or reason in {\n            "critical_feed", "feed", "care", "animal_harvest",\n            "fertilizer", "terminal_animal", "terminal_fertilizer",\n            "clear_animal_slot", "replace_incompatible_structure",\n        }\n        or operation in {"BUILD_COOP", "BUILD_PASTURE"}\n        or (operation == "PLACE" and len(job.get("action") or ()) >= 2\n            and job["action"][1] in _c06.ANIMALS)\n    )\n\n\ndef _certificate_from_tour(tour):\n    return {\n        "carry": dict((tour or {}).get("carry", {}) or {}),\n        "stops": [\n            {\n                "target": tuple(target),\n                "ops": [list(action) for action in (actions or ())],\n            }\n            for target, actions in ((tour or {}).get("stops", ()) or ())\n        ],\n        "turn_cost": int((tour or {}).get("turn_cost", 0) or 0),\n    }\n\n\ndef _next_target(certificate):\n    for stop in (certificate or {}).get("stops", ()):\n        if stop.get("ops"):\n            return tuple(stop["target"])\n    return None\n\n\ndef _plan_routes(\n    obs, farm, private, jobs, previous=None, unit_indexes=None,\n    liquidation=False,\n):\n    hour = int(obs.get("hour", 0) or 0)\n    positions = [farm["farmer"], *(farm.get("hands", []) or [])]\n    if unit_indexes is None:\n        unit_indexes = list(range(len(positions)))\n    units = [\n        router.Unit(index, tuple(positions[index]), hour)\n        for index in unit_indexes\n        if index < len(positions)\n    ]\n    shed_stock = {\n        item: max(0, int(quantity or 0))\n        for item, quantity in (private.get("shed", {}) or {}).items()\n    }\n    service_jobs = [job for job in jobs if _service_job(job)]\n    field_jobs = [job for job in jobs if not _service_job(job)]\n    service_targets = len({tuple(job["target"]) for job in service_jobs})\n    service_count = min(\n        len(units),\n        max(1, int((service_targets + 3) // 4)) if service_jobs else 0,\n    )\n    if field_jobs and service_count >= len(units) and len(units) > 1:\n        service_count = len(units) - 1\n    service_units = units[:service_count]\n    field_units = units[service_count:]\n    if not service_jobs:\n        field_units = units\n    if not field_jobs:\n        service_units = units\n\n    def solve(selected_units, selected_jobs):\n        if not selected_units or not selected_jobs:\n            return {}, _task_groups(selected_jobs)\n        fixed_owner = {}\n        if previous is not None:\n            selected_indexes = {unit.idx for unit in selected_units}\n            for index in selected_indexes:\n                target = _next_target(\n                    (previous.get("routes", {}) or {}).get(index)\n                )\n                if target is not None:\n                    fixed_owner[target] = index\n        return router.plan_day(\n            selected_units,\n            _task_groups(selected_jobs),\n            shed_stock=shed_stock,\n            fixed_owner=fixed_owner,\n            bank_outputs=liquidation,\n            deterministic_primal=True,\n        )\n\n    service_tours, service_undone = solve(service_units, service_jobs)\n    field_tours, field_undone = solve(field_units, field_jobs)\n    tours = dict(service_tours)\n    tours.update(field_tours)\n    undone = list(service_undone) + list(field_undone)\n    return {\n        unit.idx: _certificate_from_tour(tours.get(unit.idx))\n        for unit in units\n    }, undone\n\n\ndef _prune_routes(cache, live_keys):\n    for certificate in (cache.get("routes", {}) or {}).values():\n        retained = []\n        for stop in certificate.get("stops", ()):\n            target = tuple(stop["target"])\n            operations = [\n                list(action) for action in stop.get("ops", ())\n                if (target, _action_key(action)) in live_keys\n            ]\n            if operations:\n                retained.append({"target": target, "ops": operations})\n        certificate["stops"] = retained\n\n\ndef _covered_keys(cache):\n    return {\n        (tuple(stop["target"]), _action_key(action))\n        for certificate in (cache.get("routes", {}) or {}).values()\n        for stop in certificate.get("stops", ())\n        for action in stop.get("ops", ())\n    }\n\n\ndef _empty_units(cache, unit_count):\n    routes = cache.get("routes", {}) or {}\n    return [\n        index for index in range(unit_count)\n        if _next_target(routes.get(index)) is None\n    ]\n\n\ndef _live_signature(jobs):\n    return tuple(sorted(_job_key(job) for job in jobs))\n\n\ndef _ensure_routes(obs, farm, private, jobs, liquidation):\n    seat = int(obs.get("player", 0) or 0)\n    day = int(obs.get("day", 0) or 0)\n    step = int(obs.get("step", day * 24 + int(obs.get("hour", 0) or 0)) or 0)\n    unit_count = 1 + len(farm.get("hands", []) or [])\n    cache = _ROUTE_CERTIFICATES.get(seat)\n    quadrant_signature = tuple(sorted(\n        farm.get("unlocked_quadrants", []) or ["NW"]\n    ))\n    if step == 0 or (cache is not None and step < int(cache.get("step", -1))):\n        cache = None\n\n    live_keys = {_job_key(job) for job in jobs}\n    full_replan = (\n        cache is None\n        or int(cache.get("day", -1)) != day\n        or unit_count < int(cache.get("units", -1))\n        or bool(cache.get("liquidation", False)) != bool(liquidation)\n        or tuple(cache.get("quadrants", ())) != quadrant_signature\n    )\n    if cache is not None:\n        _prune_routes(cache, live_keys)\n        covered = _covered_keys(cache)\n        critical = {\n            _job_key(job) for job in jobs if int(job.get("priority", 9)) <= 0\n        }\n        service_event = any(\n            _job_key(job) not in covered\n            and _service_job(job)\n            and str((job.get("action") or ["PASS"])[0])\n            in {"BUILD_COOP", "BUILD_PASTURE", "PLACE", "FEED"}\n            for job in jobs\n        )\n        if critical - covered or service_event:\n            full_replan = True\n\n    if full_replan:\n        previous = cache\n        seed_cache = {\n            "day": day,\n            "step": step,\n            "units": unit_count,\n            "liquidation": bool(liquidation),\n            "quadrants": quadrant_signature,\n            "routes": {},\n        }\n        routes, undone = _plan_routes(\n            obs, farm, private, jobs, previous=previous,\n            liquidation=liquidation,\n        )\n        seed_cache["routes"] = routes\n        seed_cache["undone"] = len(undone)\n        cache = seed_cache\n        _ROUTE_CERTIFICATES[seat] = cache\n    else:\n        old_units = int(cache.get("units", 0) or 0)\n        for index in range(old_units, unit_count):\n            cache.setdefault("routes", {})[index] = {\n                "carry": {}, "stops": [], "turn_cost": 0,\n            }\n        cache["units"] = unit_count\n        covered = _covered_keys(cache)\n        missing_jobs = [job for job in jobs if _job_key(job) not in covered]\n        idle = _empty_units(cache, unit_count)\n        should_extend = bool(idle) and bool(missing_jobs)\n        if should_extend:\n            routes, undone = _plan_routes(\n                obs, farm, private, missing_jobs, unit_indexes=idle,\n                liquidation=liquidation,\n            )\n            cache["routes"].update(routes)\n            cache["undone"] = len(undone)\n\n    cache["step"] = step\n    return cache\n\n\ndef _remaining_requirements(certificate):\n    required = {}\n    for stop in (certificate or {}).get("stops", ()):\n        for action in stop.get("ops", ()):\n            need = _need_for(action)\n            if need is not None:\n                required[need] = required.get(need, 0) + 1\n    return required\n\n\ndef _drop_action(obs, config, farm, private, jobs, certificate, index, liquidation):\n    inventories = list(private.get("inventories", []) or [])\n    inventory = dict(inventories[index] or {}) if index < len(inventories) else {}\n    products = {\n        item: max(0, int(inventory.get(item, 0) or 0))\n        for item in _c06.PRODUCTS\n        if int(inventory.get(item, 0) or 0) > 0\n    }\n    if not products:\n        return None\n    required = _remaining_requirements(certificate)\n    if not liquidation and any(\n        int(inventory.get(item, 0) or 0) > 0 and quantity > 0\n        for item, quantity in required.items()\n    ):\n        return None\n\n    prices = ((obs.get("market", {}) or {}).get("prices", {}) or {})\n    cash_units = sum(products.values())\n    cash_value = sum(\n        quantity * float(prices.get(item, _c06.MARKET[item][0]) or _c06.MARKET[item][0])\n        for item, quantity in products.items()\n    )\n    summary = _c06._survey(farm, private, None, int(obs.get("day", 0) or 0))\n    pressure = summary["shed_load"] + summary["carried_load"]\n    cash_needed = (\n        int(obs.get("day", 0) or 0) < 22\n        and float(farm.get("money", 0) or 0) < 500\n    )\n    should_drop = (\n        liquidation\n        or pressure >= _c06.DROP_PRESSURE_THRESHOLD\n        or cash_units >= _c06.DROP_UNIT_THRESHOLD\n        or cash_value >= _c06.DROP_VALUE_THRESHOLD\n        or (cash_needed and cash_value >= _c06.CASH_DROP_VALUE_THRESHOLD)\n    )\n    if not should_drop:\n        return None\n\n    capacity = int(_c06._cfg(config, "shedCapacity", _c06.SHED_CAPACITY))\n    shed = private.get("shed", {}) or {}\n    room = max(0, capacity - sum(max(0, int(value or 0)) for value in shed.values()))\n    if room <= 0:\n        return None\n    positions = [farm["farmer"], *(farm.get("hands", []) or [])]\n    if index >= len(positions):\n        return None\n    position = tuple(positions[index])\n    sheds = _all_shed_tiles(len(farm["tiles"]))\n    if position not in sheds:\n        return _step_toward(position, _nearest_shed(position, len(farm["tiles"])))\n\n    nonproducts = sum(\n        max(0, int(quantity or 0))\n        for item, quantity in inventory.items()\n        if item not in _c06.PRODUCTS\n    )\n    if nonproducts <= 0 and cash_units <= room:\n        return ["DROP"]\n    item = max(\n        products,\n        key=lambda name: (\n            float(prices.get(name, _c06.MARKET[name][0]) or _c06.MARKET[name][0]),\n            name,\n        ),\n    )\n    quantity = min(products[item], room)\n    return ["PLACE", item, quantity] if quantity > 0 else None\n\n\ndef _route_action(obs, farm, private, certificate, index):\n    positions = [farm["farmer"], *(farm.get("hands", []) or [])]\n    if index >= len(positions):\n        return ["PASS"]\n    position = tuple(positions[index])\n    inventories = list(private.get("inventories", []) or [])\n    inventory = dict(inventories[index] or {}) if index < len(inventories) else {}\n    requirements = _remaining_requirements(certificate)\n    missing = {\n        item: max(0, quantity - int(inventory.get(item, 0) or 0))\n        for item, quantity in requirements.items()\n        if quantity > int(inventory.get(item, 0) or 0)\n    }\n    shed = private.get("shed", {}) or {}\n    available = [\n        item for item in sorted(missing, key=lambda name: (name != "WHEAT", name))\n        if int(shed.get(item, 0) or 0) > 0\n    ]\n    if available:\n        target = _nearest_shed(position, len(farm["tiles"]))\n        if position in _all_shed_tiles(len(farm["tiles"])):\n            item = available[0]\n            return ["PICKUP", item, min(missing[item], int(shed.get(item, 0) or 0))]\n        return _step_toward(position, target)\n\n    for stop in (certificate or {}).get("stops", ()):\n        if not stop.get("ops"):\n            continue\n        action = list(stop["ops"][0])\n        need = _need_for(action)\n        if need is not None and int(inventory.get(need, 0) or 0) <= 0:\n            continue\n        target = tuple(stop["target"])\n        return action if position == target else _step_toward(position, target)\n    if missing:\n        target = _nearest_shed(position, len(farm["tiles"]))\n        return ["PASS"] if position in _all_shed_tiles(len(farm["tiles"])) else _step_toward(position, target)\n    return ["PASS"]\n\n\ndef _unit_actions(obs, config, farm, private, roles):\n    day = int(obs.get("day", 0) or 0)\n    hour = int(obs.get("hour", 0) or 0)\n    step = int(obs.get("step", day * 24 + hour) or 0)\n    final_step = int(_c06._cfg(config, "episodeSteps", 720)) - 2\n    liquidation = max(0, final_step - step + 1) <= _c06.LIQUIDATION_TURNS\n    jobs = _live_jobs(obs, farm, private, roles, liquidation)\n    cache = _ensure_routes(obs, farm, private, jobs, liquidation)\n    positions = [farm["farmer"], *(farm.get("hands", []) or [])]\n    actions = []\n    for index in range(len(positions)):\n        certificate = (cache.get("routes", {}) or {}).get(index, {"stops": []})\n        action = _drop_action(\n            obs, config, farm, private, jobs, certificate, index, liquidation,\n        )\n        actions.append(action or _route_action(obs, farm, private, certificate, index))\n    return {\n        "farmer": actions[0] if actions else ["PASS"],\n        "hands": actions[1:],\n        "liquidation": liquidation,\n    }\n\n\ndef _decide(obs, config=None):\n    farms = obs.get("farms", []) or []\n    player = int(obs.get("player", 0) or 0)\n    if not (0 <= player < len(farms)):\n        return {"farmer": ["PASS"], "hands": [], "market": []}\n    farm = farms[player]\n    private = obs.get("private", {}) or {}\n    roles = _c06._role_plan(obs, farm)\n    field = _unit_actions(obs, config, farm, private, roles)\n    return {\n        "farmer": field["farmer"],\n        "hands": field["hands"],\n        "market": _c06._market_actions(obs, config, farm, private, roles, field),\n    }\n\n\ndef whitebox_v384_public_daily_route_certificate(obs, config=None):\n    try:\n        return _decide(obs, config)\n    except Exception:\n        farms = obs.get("farms", []) if hasattr(obs, "get") else []\n        player = int(obs.get("player", 0)) if hasattr(obs, "get") else 0\n        hands = (\n            len(farms[player].get("hands", []) or [])\n            if 0 <= player < len(farms) else 0\n        )\n        return {\n            "farmer": ["PASS"],\n            "hands": [["PASS"] for _ in range(hands)],\n            "market": [],\n        }\n'
_BUNDLE_SOURCES['whitebox.versions.v406_public_one_shot_melon_rotation'] = '"""V406: rotate a completed one-shot melon role into strawberry.\n\nThe certificate contains only our own publicly observed tile history. A base\nMELON role must first be witnessed as a live melon plant and later become\nempty or weeded. If strawberry has stronger current public town absorption and\nis still legal to plant, that role becomes STRAWBERRY for the rest of the\nepisode. No opponent action, identity, replay date, or coordinate is retained.\n"""\n\nfrom whitebox.versions import v361_public_wheat_rotation22 as _v361\n\n\n_c06 = _v361._c06\n_base_role_plan = _c06._role_plan\n_ROTATION_CERTIFICATES = {}\nROTATION_CAP = 10\n\n\ndef _certificate(obs):\n    player = int((obs or {}).get("player", 0) or 0)\n    step = int((obs or {}).get("step", 0) or 0)\n    current = _ROTATION_CERTIFICATES.get(player)\n    if current is None or step < int(current.get("step", -1)):\n        current = {"step": step, "seen_melons": set(), "rotated": set()}\n    current["step"] = step\n    _ROTATION_CERTIFICATES[player] = current\n    return current\n\n\ndef _role_plan(obs, farm):\n    roles = _base_role_plan(obs, farm)\n    day = int((obs or {}).get("day", 0) or 0)\n    tiles = farm.get("tiles", []) or []\n    certificate = _certificate(obs)\n    seen_melons = certificate["seen_melons"]\n    rotated = certificate["rotated"]\n\n    for position, role in roles.items():\n        if role != ("CROP", "MELON"):\n            continue\n        x, y = position\n        tile = tiles[y][x]\n        if (\n            isinstance(tile, dict)\n            and tile.get("kind") == "PLANT"\n            and tile.get("crop") == "MELON"\n        ):\n            seen_melons.add(position)\n\n    strawberry_open = day <= _c06.CROPS["STRAWBERRY"]["last_plant"]\n    demand_favors_rotation = (\n        _c06._town_demand_per_day(obs, "STRAWBERRY")\n        > _c06._town_demand_per_day(obs, "MELON")\n    )\n    if strawberry_open and demand_favors_rotation:\n        for position in sorted(seen_melons, key=lambda value: (value[1], value[0])):\n            if len(rotated) >= ROTATION_CAP:\n                break\n            x, y = position\n            tile = tiles[y][x]\n            if tile is None or (\n                isinstance(tile, dict) and tile.get("kind") == "WEED"\n            ):\n                rotated.add(position)\n\n    for position in rotated:\n        if roles.get(position) == ("CROP", "MELON"):\n            roles[position] = ("CROP", "STRAWBERRY")\n    return roles\n\n\n_c06._role_plan = _role_plan\n\n\ndef whitebox_v406_public_one_shot_melon_rotation(obs):\n    return _c06.agent(obs)\n'
_BUNDLE_SOURCES['whitebox.versions.v416_public_cow_backed_melon_rotation'] = '"""V416: rotate completed melon roles only under cow-backed service capacity.\n\nThe one-shot crop rotation is admitted only when the current visible own herd\ncontains strictly more cows than sheep. Milk has a linear oversupply penalty,\nwhile wool has a quadratic penalty in the public market curve; the guard keeps\nextra perennial crop service from disturbing a sheep-dominant sale schedule.\nAll other states retain V361\'s role map exactly.\n"""\n\nfrom whitebox.versions import v406_public_one_shot_melon_rotation as _v406\n\n\n_c06 = _v406._c06\n_base_role_plan = _v406._base_role_plan\n_ROTATION_CERTIFICATES = {}\n\n\ndef _own_animals(farm):\n    counts = {animal: 0 for animal in _c06.ANIMALS}\n    for row in farm.get("tiles", []) or []:\n        for tile in row or ():\n            if isinstance(tile, dict) and tile.get("animal") in counts:\n                counts[tile["animal"]] += 1\n    return counts\n\n\ndef _certificate(obs):\n    player = int((obs or {}).get("player", 0) or 0)\n    step = int((obs or {}).get("step", 0) or 0)\n    current = _ROTATION_CERTIFICATES.get(player)\n    if current is None or step < int(current.get("step", -1)):\n        current = {"step": step, "seen_melons": set(), "rotated": set()}\n    current["step"] = step\n    _ROTATION_CERTIFICATES[player] = current\n    return current\n\n\ndef _role_plan(obs, farm):\n    roles = _base_role_plan(obs, farm)\n    certificate = _certificate(obs)\n    seen_melons = certificate["seen_melons"]\n    rotated = certificate["rotated"]\n    tiles = farm.get("tiles", []) or []\n    for position, role in roles.items():\n        if role != ("CROP", "MELON"):\n            continue\n        x, y = position\n        tile = tiles[y][x]\n        if (\n            isinstance(tile, dict)\n            and tile.get("kind") == "PLANT"\n            and tile.get("crop") == "MELON"\n        ):\n            seen_melons.add(position)\n\n    animals = _own_animals(farm)\n    day = int((obs or {}).get("day", 0) or 0)\n    rotation_open = (\n        animals["COW"] > animals["SHEEP"]\n        and day <= _c06.CROPS["STRAWBERRY"]["last_plant"]\n        and _c06._town_demand_per_day(obs, "STRAWBERRY")\n        > _c06._town_demand_per_day(obs, "MELON")\n    )\n    if rotation_open:\n        for position in sorted(seen_melons, key=lambda value: (value[1], value[0])):\n            x, y = position\n            tile = tiles[y][x]\n            if tile is None or (\n                isinstance(tile, dict) and tile.get("kind") == "WEED"\n            ):\n                rotated.add(position)\n    for position in rotated:\n        if roles.get(position) == ("CROP", "MELON"):\n            roles[position] = ("CROP", "STRAWBERRY")\n    return roles\n\n\n_c06._role_plan = _role_plan\n\n\ndef whitebox_v416_public_cow_backed_melon_rotation(obs):\n    return _c06.agent(obs)\n'
_BUNDLE_SOURCES['whitebox.versions.v422_public_mature_demand_stickiness'] = '"""V422: admit minimal continuity only after a mature demand signal.\n\nTown shops unlock every three public days.  Before the third unlock, a single\nshop is not enough evidence to alter the route path.  From day nine onward the\none-travel-unit continuity credit is enabled only while public milk demand is\nstrictly above wool demand.  All live tasks are still rebuilt every turn.\n"""\n\nfrom whitebox.versions import v361_public_wheat_rotation22 as _v361\n\n\n_c06 = _v361._c06\n_base_unit_actions = _c06._unit_actions\n\n\ndef _unit_actions(obs, config, farm, private, roles):\n    day = int((obs or {}).get("day", 0) or 0)\n    enabled = (\n        day >= 9\n        and _c06._town_demand_per_day(obs, "MILK")\n        > _c06._town_demand_per_day(obs, "WOOL")\n    )\n    previous = _c06.TARGET_STICKINESS_BONUS\n    _c06.TARGET_STICKINESS_BONUS = _c06.TRAVEL_COST if enabled else 0.0\n    try:\n        return _base_unit_actions(obs, config, farm, private, roles)\n    finally:\n        _c06.TARGET_STICKINESS_BONUS = previous\n\n\ndef _decide(obs, config=None):\n    farms = obs.get("farms", []) or []\n    player = int(obs.get("player", 0) or 0)\n    if not (0 <= player < len(farms)):\n        return {"farmer": ["PASS"], "hands": [], "market": []}\n    farm = farms[player]\n    private = obs.get("private", {}) or {}\n    roles = _c06._role_plan(obs, farm)\n    field = _unit_actions(obs, config, farm, private, roles)\n    return {\n        "farmer": field["farmer"],\n        "hands": field["hands"],\n        "market": _c06._market_actions(\n            obs, config, farm, private, roles, field\n        ),\n    }\n\n\ndef whitebox_v422_public_mature_demand_stickiness(obs):\n    try:\n        return _decide(obs)\n    except Exception:\n        farms = obs.get("farms", []) if hasattr(obs, "get") else []\n        player = int(obs.get("player", 0)) if hasattr(obs, "get") else 0\n        hands = (\n            len(farms[player].get("hands", []) or [])\n            if 0 <= player < len(farms) else 0\n        )\n        return {\n            "farmer": ["PASS"],\n            "hands": [["PASS"] for _ in range(hands)],\n            "market": [],\n        }\n'
_BUNDLE_SOURCES['whitebox.versions.v423_public_mature_routes_cow_rotation'] = '"""V423: combine mature-demand continuity with cow-backed crop rotation.\n\nBoth mechanisms are independently public-state based.  Route continuity uses\nonly the current town demand after the third shop unlock; melon rotation uses\nonly our observed completed melon tiles, current herd composition, planting\nlegality, and current town demand.  No opponent identity or action sequence is\nretained.\n"""\n\nfrom whitebox.versions import v416_public_cow_backed_melon_rotation as _v416\nfrom whitebox.versions import v422_public_mature_demand_stickiness as _v422\n\n\n_c06 = _v416._c06\n\n\ndef whitebox_v423_public_mature_routes_cow_rotation(obs):\n    return _v422.whitebox_v422_public_mature_demand_stickiness(obs)\n'
_BUNDLE_SOURCES['whitebox.versions.v448_public_unfunded_seed_cash'] = '"""V448: release exact sale cash only for an unfunded expansion seed plan.\n\nOn day eight, substantial open land certifies that the first expansion still\nhas crop work available.  The conservative V423 market plan is built first.\nOnly when that plan cannot fund any already named seed does the policy rebuild\nthe same public-state market plan with engine-exact same-turn sale cash.\nCapital, field routing, and plans that already buy seed remain unchanged.\n"""\n\nfrom whitebox.versions import v423_public_mature_routes_cow_rotation as _v423\n\n\n_c06 = _v423._c06\n_unit_actions = _v423._v422._unit_actions\n\n\ndef _open_land(farm):\n    return sum(\n        tile is None or (\n            isinstance(tile, dict) and tile.get("kind") == "WEED"\n        )\n        for row in farm.get("tiles", []) or []\n        for tile in row or ()\n    )\n\n\ndef _buys_seed(orders):\n    return any(\n        isinstance(order, list)\n        and len(order) >= 2\n        and order[0] == "BUY_SEED"\n        and int(order[2] if len(order) >= 3 else 1) > 0\n        for order in orders or ()\n    )\n\n\ndef _decide(obs, config=None):\n    farms = obs.get("farms", []) or []\n    player = int(obs.get("player", 0) or 0)\n    if not (0 <= player < len(farms)):\n        return {"farmer": ["PASS"], "hands": [], "market": []}\n    farm = farms[player]\n    private = obs.get("private", {}) or {}\n    roles = _c06._role_plan(obs, farm)\n    field = _unit_actions(obs, config, farm, private, roles)\n    market = _c06._market_actions(obs, config, farm, private, roles, field)\n    certified = (\n        int(obs.get("day", 0) or 0) == 8\n        and len(farm.get("unlocked_quadrants", []) or []) == 2\n        and _open_land(farm) >= 16\n        and not _buys_seed(market)\n    )\n    if certified:\n        previous = _c06.COMMITTED_WORK_SALE_CASH_FACTOR\n        _c06.COMMITTED_WORK_SALE_CASH_FACTOR = 1.0\n        try:\n            market = _c06._market_actions(\n                obs, config, farm, private, roles, field\n            )\n        finally:\n            _c06.COMMITTED_WORK_SALE_CASH_FACTOR = previous\n    return {\n        "farmer": field["farmer"],\n        "hands": field["hands"],\n        "market": market,\n    }\n\n\ndef whitebox_v448_public_unfunded_seed_cash(obs):\n    try:\n        return _decide(obs)\n    except Exception:\n        farms = obs.get("farms", []) if hasattr(obs, "get") else []\n        player = int(obs.get("player", 0)) if hasattr(obs, "get") else 0\n        hand_count = (\n            len(farms[player].get("hands", []) or [])\n            if 0 <= player < len(farms) else 0\n        )\n        return {\n            "farmer": ["PASS"],\n            "hands": [["PASS"] for _ in range(hand_count)],\n            "market": [],\n        }\n'
_BUNDLE_SOURCES['whitebox.versions.v452_public_cow_service_commitment'] = '"""V452: stabilize cow-dominant service routes at the late growth peak.\n\nOn day seventeen, a cow-dominant mature herd under stronger public milk demand\ncreates a dense daily feed, care, fertilizer, and harvest route.  This visible\ncertificate credits six movement turns for retaining a still-live target.\nSheep-dominant farms and all other days keep V448\'s existing route policy.\n"""\n\nfrom whitebox.versions import v448_public_unfunded_seed_cash as _v448\n\n\n_c06 = _v448._c06\n_base_unit_actions = _v448._v423._v422._base_unit_actions\n\n\ndef _own_animals(farm):\n    counts = {animal: 0 for animal in _c06.ANIMALS}\n    for row in farm.get("tiles", []) or []:\n        for tile in row or ():\n            if isinstance(tile, dict) and tile.get("animal") in counts:\n                counts[tile["animal"]] += 1\n    return counts\n\n\ndef _cow_service_peak(obs, farm):\n    animals = _own_animals(farm)\n    return (\n        int((obs or {}).get("day", 0) or 0) == 17\n        and animals["COW"] > animals["SHEEP"]\n        and _c06._town_demand_per_day(obs, "MILK")\n        > _c06._town_demand_per_day(obs, "WOOL")\n    )\n\n\ndef _unit_actions(obs, config, farm, private, roles):\n    day = int((obs or {}).get("day", 0) or 0)\n    mature = (\n        day >= 9\n        and _c06._town_demand_per_day(obs, "MILK")\n        > _c06._town_demand_per_day(obs, "WOOL")\n    )\n    previous = _c06.TARGET_STICKINESS_BONUS\n    _c06.TARGET_STICKINESS_BONUS = (\n        6.0 * _c06.TRAVEL_COST\n        if _cow_service_peak(obs, farm)\n        else _c06.TRAVEL_COST if mature else 0.0\n    )\n    try:\n        return _base_unit_actions(obs, config, farm, private, roles)\n    finally:\n        _c06.TARGET_STICKINESS_BONUS = previous\n\n\n_v448._unit_actions = _unit_actions\n\n\ndef whitebox_v452_public_cow_service_commitment(obs):\n    return _v448.whitebox_v448_public_unfunded_seed_cash(obs)\n'
_BUNDLE_SOURCES['whitebox.versions.v454_public_weed_window_sale_cash'] = '"""V454: use exact early sale cash during a visible rival weed delay.\n\nOn day two, a clean own field with open land can immediately deploy committed\nseed.  Exact sale cash is released only while another public farm has a weed,\nwhich certifies a competing service delay.  Without that delay, V452\'s\nconservative buffer avoids entering a synchronized crop expansion race.\n"""\n\nfrom whitebox.versions import v452_public_cow_service_commitment as _v452\n\n\n_c06 = _v452._c06\n\n\ndef _field_counts(farm):\n    open_cells = 0\n    weeds = 0\n    for row in farm.get("tiles", []) or []:\n        for tile in row or ():\n            if tile is None:\n                open_cells += 1\n            elif isinstance(tile, dict) and tile.get("kind") == "WEED":\n                weeds += 1\n    return open_cells, weeds\n\n\ndef _weed_window(obs):\n    farms = (obs or {}).get("farms", []) or []\n    player = int((obs or {}).get("player", 0) or 0)\n    if not (0 <= player < len(farms)):\n        return False\n    own_open, own_weeds = _field_counts(farms[player])\n    rival_weeds = sum(\n        _field_counts(farm)[1]\n        for index, farm in enumerate(farms)\n        if index != player\n    )\n    return (\n        int((obs or {}).get("day", 0) or 0) == 2\n        and own_open > 0\n        and own_weeds == 0\n        and rival_weeds > 0\n    )\n\n\ndef whitebox_v454_public_weed_window_sale_cash(obs):\n    previous = _c06.SALE_CASH_FACTOR\n    _c06.SALE_CASH_FACTOR = 1.0 if _weed_window(obs) else 0.85\n    try:\n        return _v452.whitebox_v452_public_cow_service_commitment(obs)\n    finally:\n        _c06.SALE_CASH_FACTOR = previous\n'
_BUNDLE_SOURCES['whitebox.versions.v463_public_receding_routes'] = '"""V463: re-solve current public work as receding day routes every turn.\n\nEach observation exposes the complete currently live task set, current worker\npositions and carried inputs.  This layer groups same-tile operations, solves\nan open multi-worker route over the remaining hours of the current day, and\nemits only the first action of each route.  The solve is repeated from the next\nlive observation, so newly appearing feed, harvest, weed, and capital tasks\nenter immediately and stale work disappears without a retained action tape.\n"""\n\nfrom route import router\nfrom whitebox.versions import v384_public_daily_route_certificate as _v384\nfrom whitebox.versions import v454_public_weed_window_sale_cash as _v454\n\n\n_c06 = _v454._c06\n\n\ndef _route_action(farm, private, tour, index):\n    positions = [farm["farmer"], *(farm.get("hands", []) or [])]\n    if index >= len(positions):\n        return ["PASS"]\n    position = tuple(positions[index])\n    inventories = list(private.get("inventories", []) or [])\n    inventory = (\n        dict(inventories[index] or {})\n        if index < len(inventories)\n        else {}\n    )\n    carry = dict((tour or {}).get("carry", {}) or {})\n    missing = {\n        item: max(0, int(quantity) - int(inventory.get(item, 0) or 0))\n        for item, quantity in carry.items()\n        if int(quantity) > int(inventory.get(item, 0) or 0)\n    }\n    shed = private.get("shed", {}) or {}\n    available = [\n        item\n        for item in sorted(missing, key=lambda name: (name != "WHEAT", name))\n        if int(shed.get(item, 0) or 0) > 0\n    ]\n    if available:\n        target = _c06._nearest_shed(\n            position, len(farm["tiles"]), farm["tiles"]\n        )\n        if position in _c06._shed_tiles(len(farm["tiles"]), farm["tiles"]):\n            item = available[0]\n            return [\n                "PICKUP",\n                item,\n                min(missing[item], int(shed.get(item, 0) or 0)),\n            ]\n        return _c06._bfs_first_step(farm["tiles"], position, target)\n\n    for target, operations in (tour or {}).get("stops", ()) or ():\n        if not operations:\n            continue\n        action = list(operations[0])\n        need = _v384._need_for(action)\n        if need is not None and int(inventory.get(need, 0) or 0) <= 0:\n            continue\n        target = tuple(target)\n        return (\n            action\n            if position == target\n            else _c06._bfs_first_step(farm["tiles"], position, target)\n        )\n    return ["PASS"]\n\n\ndef _unit_actions(obs, config, farm, private, roles):\n    day = int(obs.get("day", 0) or 0)\n    hour = int(obs.get("hour", 0) or 0)\n    step = int(obs.get("step", day * 24 + hour) or 0)\n    final_step = int(_c06._cfg(config, "episodeSteps", 720)) - 2\n    actions_left = max(0, final_step - step + 1)\n    liquidation = actions_left <= _c06.LIQUIDATION_TURNS\n    jobs = _v384._live_jobs(obs, farm, private, roles, liquidation)\n    positions = [farm["farmer"], *(farm.get("hands", []) or [])]\n    units = [\n        router.Unit(index, tuple(position), hour)\n        for index, position in enumerate(positions)\n    ]\n    shed_stock = {\n        item: max(0, int(quantity or 0))\n        for item, quantity in (private.get("shed", {}) or {}).items()\n    }\n    tours, _undone = router.plan_day(\n        units,\n        _v384._task_groups(jobs),\n        shed_stock=shed_stock,\n        bank_outputs=liquidation,\n        deterministic_primal=True,\n    )\n    actions = [\n        _route_action(farm, private, tours.get(index), index)\n        for index in range(len(positions))\n    ]\n    return {\n        "farmer": actions[0] if actions else ["PASS"],\n        "hands": actions[1:],\n        "liquidation": liquidation,\n    }\n\n\ndef _decide(obs, config=None):\n    farms = obs.get("farms", []) or []\n    player = int(obs.get("player", 0) or 0)\n    if not (0 <= player < len(farms)):\n        return {"farmer": ["PASS"], "hands": [], "market": []}\n    farm = farms[player]\n    private = obs.get("private", {}) or {}\n    roles = _c06._role_plan(obs, farm)\n    field = _unit_actions(obs, config, farm, private, roles)\n    return {\n        "farmer": field["farmer"],\n        "hands": field["hands"],\n        "market": _c06._market_actions(\n            obs, config, farm, private, roles, field\n        ),\n    }\n\n\ndef whitebox_v463_public_receding_routes(obs, config=None):\n    try:\n        return _decide(obs, config)\n    except Exception:\n        farms = obs.get("farms", []) if hasattr(obs, "get") else []\n        player = int(obs.get("player", 0)) if hasattr(obs, "get") else 0\n        hands = (\n            len(farms[player].get("hands", []) or [])\n            if 0 <= player < len(farms)\n            else 0\n        )\n        return {\n            "farmer": ["PASS"],\n            "hands": [["PASS"] for _ in range(hands)],\n            "market": [],\n        }\n'
_BUNDLE_SOURCES['whitebox.versions.v464_public_carried_input_routes'] = '"""V464: receding public routes with exact carried-input ownership.\n\nThe public route solver prices shared shed stock, while live workers may\nalready carry feed, fertilizer, or an animal.  Treating that carried input as\nunowned made the selected task migrate to another worker every turn and forced\nrepeated pickups.  This layer assigns each worker with a relevant carried item\nto its nearest matching live task, removes exactly one unit of that task\'s\nshed requirement, and jointly routes the remaining work.  The reservation is\nrebuilt from the current private inventory and live tasks every observation.\n"""\n\nfrom route import router\nfrom whitebox.versions import v463_public_receding_routes as _v463\n\n\n_v384 = _v463._v384\n_c06 = _v463._c06\n\n\ndef _copy_task(task, carry):\n    return router.Task(\n        task.pos,\n        [list(action) for action in task.ops],\n        carry=carry,\n        value=task.value,\n        mandatory=task.mandatory,\n        kind=task.kind,\n        cash_cost=task.cash_cost,\n        order_key=task.order_key,\n        activations=task.activations,\n        exclusive_key=task.exclusive_key,\n    )\n\n\ndef _reserve_carried_inputs(tasks, positions, inventories):\n    tasks = list(tasks)\n    fixed_owner = {}\n    reserved = set()\n    for worker, raw_position in enumerate(positions):\n        inventory = (\n            dict(inventories[worker] or {})\n            if worker < len(inventories)\n            else {}\n        )\n        candidates = []\n        for index, task in enumerate(tasks):\n            if index in reserved:\n                continue\n            usable = [\n                item\n                for item, quantity in task.carry.items()\n                if int(quantity) > 0\n                and int(inventory.get(item, 0) or 0) > 0\n            ]\n            if not usable:\n                continue\n            candidates.append((\n                _c06._distance(raw_position, task.pos),\n                0 if task.mandatory else 1,\n                tuple(task.pos),\n                index,\n                sorted(usable, key=lambda item: (item != "WHEAT", item))[0],\n            ))\n        if not candidates:\n            continue\n        _distance, _optional, target, index, item = min(candidates)\n        carry = dict(tasks[index].carry)\n        carry[item] = max(0, int(carry.get(item, 0) or 0) - 1)\n        if carry[item] == 0:\n            del carry[item]\n        tasks[index] = _copy_task(tasks[index], carry)\n        fixed_owner[target] = worker\n        reserved.add(index)\n    return tasks, fixed_owner\n\n\ndef _unit_actions(obs, config, farm, private, roles):\n    day = int(obs.get("day", 0) or 0)\n    hour = int(obs.get("hour", 0) or 0)\n    step = int(obs.get("step", day * 24 + hour) or 0)\n    final_step = int(_c06._cfg(config, "episodeSteps", 720)) - 2\n    actions_left = max(0, final_step - step + 1)\n    liquidation = actions_left <= _c06.LIQUIDATION_TURNS\n    jobs = _v384._live_jobs(obs, farm, private, roles, liquidation)\n    positions = [farm["farmer"], *(farm.get("hands", []) or [])]\n    inventories = list(private.get("inventories", []) or [])\n    tasks, fixed_owner = _reserve_carried_inputs(\n        _v384._task_groups(jobs), positions, inventories\n    )\n    units = [\n        router.Unit(index, tuple(position), hour)\n        for index, position in enumerate(positions)\n    ]\n    shed_stock = {\n        item: max(0, int(quantity or 0))\n        for item, quantity in (private.get("shed", {}) or {}).items()\n    }\n    tours, _undone = router.plan_day(\n        units,\n        tasks,\n        shed_stock=shed_stock,\n        fixed_owner=fixed_owner,\n        bank_outputs=liquidation,\n        deterministic_primal=True,\n    )\n    actions = [\n        _v463._route_action(farm, private, tours.get(index), index)\n        for index in range(len(positions))\n    ]\n    return {\n        "farmer": actions[0] if actions else ["PASS"],\n        "hands": actions[1:],\n        "liquidation": liquidation,\n    }\n\n\ndef _decide(obs, config=None):\n    farms = obs.get("farms", []) or []\n    player = int(obs.get("player", 0) or 0)\n    if not (0 <= player < len(farms)):\n        return {"farmer": ["PASS"], "hands": [], "market": []}\n    farm = farms[player]\n    private = obs.get("private", {}) or {}\n    roles = _c06._role_plan(obs, farm)\n    field = _unit_actions(obs, config, farm, private, roles)\n    return {\n        "farmer": field["farmer"],\n        "hands": field["hands"],\n        "market": _c06._market_actions(\n            obs, config, farm, private, roles, field\n        ),\n    }\n\n\ndef whitebox_v464_public_carried_input_routes(obs, config=None):\n    try:\n        return _decide(obs, config)\n    except Exception:\n        farms = obs.get("farms", []) if hasattr(obs, "get") else []\n        player = int(obs.get("player", 0)) if hasattr(obs, "get") else 0\n        hands = (\n            len(farms[player].get("hands", []) or [])\n            if 0 <= player < len(farms)\n            else 0\n        )\n        return {\n            "farmer": ["PASS"],\n            "hands": [["PASS"] for _ in range(hands)],\n            "market": [],\n        }\n'
_BUNDLE_SOURCES['whitebox.versions.v545_public_state_route_selector'] = '"""V545: select a public-state route family from the first expansion signal.\n\nThe selector has three generic modes: a wheat-heavy public crop book, a\nlighter animal footprint when the visible book is animal-heavy but not\nstrawberry-heavy, and the audited V454 default.  It stores only the current\nseat\'s mode and resets it when the episode step rewinds; no opponent label,\nseed, seat pairing, or future action is referenced.\n"""\n\nfrom whitebox.versions import v454_public_weed_window_sale_cash as _v454\n\n\n_c06 = _v454._c06\n_base_herd_targets = _c06._herd_targets\n_base_slots = dict(_c06.ANIMAL_SLOTS)\n_base_crop_mix = dict(_c06.CROP_MIX)\n_base_max_hands = _c06.MAX_HANDS\n_MODE = {}\n_LAST_STEP = {}\n\n_WHEAT30 = {\n    "NW": {"MELON": 10, "WHEAT": 10, "CARROT": 2},\n    "NE": {"WHEAT": 10, "CARROT": 1},\n    "SW": {"WHEAT": 10, "CARROT": 1},\n    "SE": {"WHEAT": 10, "CARROT": 2},\n}\n\n\ndef _counts(farm):\n    crops = {"STRAWBERRY": 0, "WHEAT": 0, "MELON": 0}\n    animals = {"COW": 0, "SHEEP": 0}\n    for row in farm.get("tiles", []) or ():\n        for tile in row or ():\n            if not isinstance(tile, dict):\n                continue\n            if tile.get("crop") in crops:\n                crops[tile["crop"]] += 1\n            if tile.get("animal") in animals:\n                animals[tile["animal"]] += 1\n    return crops, animals\n\n\ndef _update_mode(obs):\n    player = int((obs or {}).get("player", 0) or 0)\n    step = int((obs or {}).get("step", 0) or 0)\n    if step == 0 or step < _LAST_STEP.get(player, -1):\n        _MODE.pop(player, None)\n    _LAST_STEP[player] = step\n    day = int((obs or {}).get("day", 0) or 0)\n    farms = (obs or {}).get("farms", []) or []\n    if player in _MODE or not (6 <= day <= 12):\n        return _MODE.get(player, "default")\n    for index, rival in enumerate(farms):\n        if index == player:\n            continue\n        crops, animals = _counts(rival)\n        if crops["WHEAT"] >= 9 and crops["STRAWBERRY"] < 15:\n            _MODE[player] = "wheat"\n            return "wheat"\n        if sum(animals.values()) >= 8 and crops["STRAWBERRY"] < 15:\n            _MODE[player] = "light"\n            return "light"\n    return "default"\n\n\ndef _herd_targets(obs, farm, private, capacity):\n    raw = _base_herd_targets(obs, farm, private, capacity)\n    player = int((obs or {}).get("player", 0) or 0)\n    if _MODE.get(player) != "light":\n        return raw\n    total = sum(raw.values())\n    target = min(13, max(total, 4))\n    if total <= target:\n        return raw\n    cows = min(raw.get("COW", 0), target - 1)\n    return {"COW": cows, "SHEEP": max(1, target - cows)}\n\n\n_c06._herd_targets = _herd_targets\n\n\ndef whitebox_v545_public_state_route_selector(obs):\n    mode = _update_mode(obs)\n    old_slots = _c06.ANIMAL_SLOTS\n    old_mix = _c06.CROP_MIX\n    old_hands = _c06.MAX_HANDS\n    if mode == "light":\n        _c06.ANIMAL_SLOTS = {"NW": 4, "NE": 5, "SW": 4, "SE": 0}\n        _c06.CROP_MIX = dict(_base_crop_mix)\n        _c06.MAX_HANDS = 14\n    elif mode == "wheat":\n        _c06.ANIMAL_SLOTS = dict(_base_slots)\n        _c06.CROP_MIX = dict(_WHEAT30)\n        _c06.MAX_HANDS = _base_max_hands\n    else:\n        _c06.ANIMAL_SLOTS = dict(_base_slots)\n        _c06.CROP_MIX = dict(_base_crop_mix)\n        _c06.MAX_HANDS = _base_max_hands\n    try:\n        return _v454.whitebox_v454_public_weed_window_sale_cash(obs)\n    finally:\n        _c06.ANIMAL_SLOTS = old_slots\n        _c06.CROP_MIX = old_mix\n        _c06.MAX_HANDS = old_hands\n'
_BUNDLE_SOURCES['whitebox.versions.v546_public_state_wheat_only'] = '"""V546: retain the public wheat signal while rejecting the light footprint."""\n\nfrom whitebox.versions import v545_public_state_route_selector as _v545\n\n\n_base_update_mode = _v545._update_mode\n\n\ndef _update_mode(obs):\n    mode = _base_update_mode(obs)\n    if mode == "light":\n        player = int((obs or {}).get("player", 0) or 0)\n        _v545._MODE[player] = "default"\n        return "default"\n    return mode\n\n\n_v545._update_mode = _update_mode\n\n\ndef whitebox_v546_public_state_wheat_only(obs):\n    return _v545.whitebox_v545_public_state_route_selector(obs)\n'
_BUNDLE_SOURCES['whitebox.versions.v608_public_sticky_low_wheat_route'] = '"""V608: sticky public low-wheat market route.\n\nOnce a route is selected from the public signal it remains fixed for the\nepisode, matching V545\'s certificate semantics.  The earlier challenger\nincorrectly re-tested the low-wheat condition after later replanting.\n"""\n\nfrom whitebox.versions import v546_public_state_wheat_only as _v546\n\n\n_v545 = _v546._v545\n_base_public_selector = _v546._base_update_mode\n_FULL = dict(_v545._base_slots)\n_WHEAT_SLOTS = {"NW": 4, "NE": 5, "SW": 4, "SE": 0}\n\n\ndef _low_wheat_animals(obs):\n    player = int((obs or {}).get("player", 0) or 0)\n    for index, rival in enumerate((obs or {}).get("farms", []) or ()):\n        if index == player:\n            continue\n        wheat = animals = 0\n        for row in rival.get("tiles", []) or ():\n            for tile in row or ():\n                if not isinstance(tile, dict):\n                    continue\n                wheat += tile.get("crop") == "WHEAT"\n                animals += bool(tile.get("animal"))\n        if animals >= 8 and wheat <= 5:\n            return True\n    return False\n\n\ndef _wool_favorable(obs):\n    prices = ((obs or {}).get("market", {}) or {}).get("prices", {}) or {}\n    return float(prices.get("WOOL", 200) or 200) >= float(\n        prices.get("MILK", 160) or 160\n    )\n\n\ndef _update_mode(obs):\n    player = int((obs or {}).get("player", 0) or 0)\n    step = int((obs or {}).get("step", 0) or 0)\n    if step == 0 or step < _v545._LAST_STEP.get(player, -1):\n        _v545._MODE.pop(player, None)\n    _v545._LAST_STEP[player] = step\n    existing = _v545._MODE.get(player)\n    if existing in {"light", "wheat", "default"}:\n        mode = existing\n    else:\n        mode = _base_public_selector(obs)\n        if mode == "light" and not (\n            _low_wheat_animals(obs) and _wool_favorable(obs)\n        ):\n            _v545._MODE[player] = "default"\n            mode = "default"\n    _v545._base_slots = dict(_WHEAT_SLOTS if mode == "wheat" else _FULL)\n    return mode\n\n\n_v545._update_mode = _update_mode\n\n\ndef whitebox_v608_public_sticky_low_wheat_route(obs):\n    return _v546.whitebox_v546_public_state_wheat_only(obs)\n'
_BUNDLE_SOURCES['whitebox.versions.v623_public_light_farmers_cow6'] = '"""V623: public FARMERS_MARKET light route with six cows."""\n\nfrom whitebox.versions import v608_public_sticky_low_wheat_route as _v608\n\n\n_v545 = _v608._v545\n_v454 = _v545._v454\n_c06 = _v545._c06\n_base_targets = _v545._base_herd_targets\n_FULL = dict(_v545._base_slots)\n_WHEAT = {"NW": 4, "NE": 5, "SW": 4, "SE": 0}\n\n\ndef _farmers_market(obs):\n    shops = ((obs or {}).get("town", {}) or {}).get("unlocked_shops", []) or []\n    return "FARMERS_MARKET" in shops\n\n\ndef _herd_targets(obs, farm, private, capacity):\n    raw = _base_targets(obs, farm, private, capacity)\n    player = int((obs or {}).get("player", 0) or 0)\n    if _v545._MODE.get(player) != "light" or not _farmers_market(obs):\n        return raw\n    total = min(int(capacity), sum(raw.values()), 13)\n    if total < 4:\n        return raw\n    cows = min(total, 6)\n    return {"COW": cows, "SHEEP": max(0, total - cows)}\n\n\n_c06._herd_targets = _herd_targets\n\n\ndef _route(obs):\n    mode = _v545._update_mode(obs)\n    old_slots, old_mix, old_hands = _c06.ANIMAL_SLOTS, _c06.CROP_MIX, _c06.MAX_HANDS\n    if mode == "light":\n        _c06.ANIMAL_SLOTS = {"NW": 4, "NE": 5, "SW": 4, "SE": 0}\n        _c06.CROP_MIX = dict(_v545._base_crop_mix)\n        _c06.MAX_HANDS = 14\n    elif mode == "wheat":\n        _c06.ANIMAL_SLOTS = dict(_WHEAT)\n        _c06.CROP_MIX = dict(_v545._WHEAT30)\n        _c06.MAX_HANDS = _v545._base_max_hands\n    else:\n        _c06.ANIMAL_SLOTS = dict(_FULL)\n        _c06.CROP_MIX = dict(_v545._base_crop_mix)\n        _c06.MAX_HANDS = _v545._base_max_hands\n    try:\n        return _v454.whitebox_v454_public_weed_window_sale_cash(obs)\n    finally:\n        _c06.ANIMAL_SLOTS, _c06.CROP_MIX, _c06.MAX_HANDS = old_slots, old_mix, old_hands\n\n\n_v545.whitebox_v545_public_state_route_selector = _route\n\n\ndef whitebox_v623_public_light_farmers_cow6(obs):\n    return _v608.whitebox_v608_public_sticky_low_wheat_route(obs)\n'
_BUNDLE_SOURCES['whitebox.versions.v629_public_shop_adaptive_hands'] = '"""V629: public-shop adaptive light-route hand capacity.\n\nThe light route keeps fourteen hands for the yarn-led opening, where crop\nservice is the binding capacity, and caps at twelve hands after a public\nfarmers-market opening, where early capital is tighter.  The branch uses only\nthe current town observation and the retained generic light certificate.\n"""\n\nfrom whitebox.versions import v623_public_light_farmers_cow6 as _v623\n\n\n_v545 = _v623._v545\n_c06 = _v545._c06\n_base_target_hands = _c06._target_hands\n\n\ndef _target_hands(obs, farm, private, roles):\n    value = _base_target_hands(obs, farm, private, roles)\n    player = int((obs or {}).get("player", 0) or 0)\n    if _v545._MODE.get(player) != "light":\n        return value\n    shops = ((obs or {}).get("town", {}) or {}).get("unlocked_shops", []) or []\n    cap = 12 if "FARMERS_MARKET" in shops else 14\n    return min(int(value), cap)\n\n\n_c06._target_hands = _target_hands\n\n\ndef whitebox_v629_public_shop_adaptive_hands(obs):\n    return _v623.whitebox_v623_public_light_farmers_cow6(obs)\n'
_BUNDLE_SOURCES['whitebox.versions.v645_public_farmers_carried_routes'] = '"""V645: carried-input routes for the public FARMERS_MARKET light state.\n\nThe receding route solver raises crop throughput on the light route when the\nvisible town opens with FARMERS_MARKET, but delays land and capital turnover\nin the YARN_STORE opening.  This wrapper therefore enables the transparent\nlive-state route solver only for the former public state.  All other states\nuse V629 unchanged.\n"""\n\nfrom whitebox.versions import v629_public_shop_adaptive_hands as _v629\nfrom whitebox.versions import v464_public_carried_input_routes as _v464\n\n\n_v623 = _v629._v623\n_v545 = _v623._v545\n_c06 = _v545._c06\n_base_selector = _v545.whitebox_v545_public_state_route_selector\n\n\ndef _farmers_market(obs):\n    shops = ((obs or {}).get("town", {}) or {}).get("unlocked_shops", []) or []\n    return "FARMERS_MARKET" in shops\n\n\ndef _selector(obs):\n    mode = _v545._update_mode(obs)\n    if mode != "light" or not _farmers_market(obs):\n        return _base_selector(obs)\n    farms = (obs or {}).get("farms", []) or []\n    player = int((obs or {}).get("player", 0) or 0)\n    if not (0 <= player < len(farms)):\n        return {"farmer": ["PASS"], "hands": [], "market": []}\n    farm = farms[player]\n    private = (obs or {}).get("private", {}) or {}\n    old_slots = _c06.ANIMAL_SLOTS\n    old_mix = _c06.CROP_MIX\n    old_hands = _c06.MAX_HANDS\n    _c06.ANIMAL_SLOTS = {"NW": 4, "NE": 5, "SW": 4, "SE": 0}\n    _c06.CROP_MIX = dict(_v545._base_crop_mix)\n    _c06.MAX_HANDS = 12\n    try:\n        roles = _c06._role_plan(obs, farm)\n        field = _v464._unit_actions(obs, None, farm, private, roles)\n        return {\n            "farmer": field["farmer"],\n            "hands": field["hands"],\n            "market": _c06._market_actions(obs, None, farm, private, roles, field),\n        }\n    finally:\n        _c06.ANIMAL_SLOTS = old_slots\n        _c06.CROP_MIX = old_mix\n        _c06.MAX_HANDS = old_hands\n\n\n_v545.whitebox_v545_public_state_route_selector = _selector\n\n\ndef whitebox_v645_public_farmers_carried_routes(obs):\n    return _v629.whitebox_v629_public_shop_adaptive_hands(obs)\n'
_BUNDLE_SOURCES['whitebox.versions.v646_public_farmers_late_rotation'] = '"""V646: late short-crop rotation in the public FARMERS_MARKET light state.\n\nAfter a long-cycle role\'s public planting deadline, an empty or weeded tile\ncan no longer execute that role.  In the FARMERS_MARKET light state only,\nrotate such tiles to wheat while wheat can still mature, then carrot while\ncarrot can still mature.  Existing plants and every non-matching public state\nremain unchanged.\n"""\n\nfrom whitebox.versions import v645_public_farmers_carried_routes as _v645\n\n\n_v629 = _v645._v629\n_v623 = _v645._v623\n_v545 = _v645._v545\n_c06 = _v645._c06\n_base_role_plan = _c06._role_plan\n\n\ndef _role_plan(obs, farm):\n    roles = _base_role_plan(obs, farm)\n    player = int((obs or {}).get("player", 0) or 0)\n    if _v545._MODE.get(player) != "light" or not _v645._farmers_market(obs):\n        return roles\n    day = int((obs or {}).get("day", 0) or 0)\n    tiles = farm.get("tiles", []) or []\n    for position, role in tuple(roles.items()):\n        kind, crop = role\n        if kind != "CROP" or day <= _c06.CROPS[crop]["last_plant"]:\n            continue\n        x, y = position\n        tile = tiles[y][x]\n        if not (\n            tile is None\n            or (isinstance(tile, dict) and tile.get("kind") == "WEED")\n        ):\n            continue\n        if day <= _c06.CROPS["WHEAT"]["last_plant"]:\n            roles[position] = ("CROP", "WHEAT")\n        elif day <= _c06.CROPS["CARROT"]["last_plant"]:\n            roles[position] = ("CROP", "CARROT")\n    return roles\n\n\n_c06._role_plan = _role_plan\n\n\ndef whitebox_v646_public_farmers_late_rotation(obs):\n    return _v629.whitebox_v629_public_shop_adaptive_hands(obs)\n'
_BUNDLE_SOURCES['whitebox.versions.v649_public_farmers_immediate_sales'] = '"""V649: immediately sell banked outputs in the FARMERS_MARKET light state.\n\nCurrent shed output is an exposed position on the shared public price curve.\nFor the FARMERS_MARKET light route, sell all already banked non-input output\nat the current quote while retaining V646\'s wheat and fertilizer reserves.\nProduction, land, crew, and routing decisions are unchanged.\n"""\n\nfrom whitebox.versions import v646_public_farmers_late_rotation as _v646\n\n\n_v645 = _v646._v645\n_v545 = _v646._v545\n_c06 = _v646._c06\n_base_market_actions = _c06._market_actions\n_OUTPUTS = tuple(\n    item for item in _c06.PRODUCTS if item not in {"WHEAT", "FERTILIZER"}\n)\n\n\ndef _market_actions(obs, config, farm, private, roles, field):\n    orders = [list(order) for order in _base_market_actions(\n        obs, config, farm, private, roles, field\n    )]\n    player = int((obs or {}).get("player", 0) or 0)\n    if _v545._MODE.get(player) != "light" or not _v645._farmers_market(obs):\n        return orders\n    capacity = int(_c06._cfg(config, "shedCapacity", _c06.SHED_CAPACITY))\n    shed, _inventories = _c06._post_field_storage(private, field, capacity)\n    by_item = {\n        order[1]: index\n        for index, order in enumerate(orders)\n        if len(order) >= 3 and order[0] == "SELL"\n    }\n    max_orders = int(_c06._cfg(\n        config, "maxMarketOrdersPerTurn", _c06.MAX_MARKET_ORDERS\n    ))\n    for item in _OUTPUTS:\n        quantity = max(0, int(shed.get(item, 0) or 0))\n        if quantity <= 0:\n            continue\n        if item in by_item:\n            orders[by_item[item]][2] = quantity\n        elif len(orders) < max_orders:\n            by_item[item] = len(orders)\n            orders.append(["SELL", item, quantity])\n    return orders[:max_orders]\n\n\n_c06._market_actions = _market_actions\n\n\ndef whitebox_v649_public_farmers_immediate_sales(obs):\n    return _v646.whitebox_v646_public_farmers_late_rotation(obs)\n'
_BUNDLE_SOURCES['whitebox.versions.v659_public_idle_undone_refill'] = '"""V659: refill genuinely idle workers from live undone public tasks.\n\nV649\'s receding solver may leave positive-value work unassigned while some\nunits emit PASS.  Reuse only the solver\'s explicit ``undone`` set: each idle\nunit takes the nearest distinct task that needs no carried input and whose\ntravel plus operations fit the remaining public day budget.  Assigned routes,\ncapital, market orders, and every input-constrained task remain unchanged.\n"""\n\nfrom whitebox.versions import v649_public_farmers_immediate_sales as _v649\n\n\n_v464 = _v649._v646._v645._v464\n_v463 = _v464._v463\n_v384 = _v464._v384\n_c06 = _v649._c06\n\n\ndef _unit_actions(obs, config, farm, private, roles):\n    day = int((obs or {}).get("day", 0) or 0)\n    hour = int((obs or {}).get("hour", 0) or 0)\n    step = int((obs or {}).get("step", day * 24 + hour) or 0)\n    final_step = int(_c06._cfg(config, "episodeSteps", 720)) - 2\n    actions_left = max(0, final_step - step + 1)\n    liquidation = actions_left <= _c06.LIQUIDATION_TURNS\n    jobs = _v384._live_jobs(obs, farm, private, roles, liquidation)\n    positions = [farm["farmer"], *(farm.get("hands", []) or [])]\n    inventories = list(private.get("inventories", []) or [])\n    tasks, fixed_owner = _v464._reserve_carried_inputs(\n        _v384._task_groups(jobs), positions, inventories\n    )\n    units = [\n        _v464.router.Unit(index, tuple(position), hour)\n        for index, position in enumerate(positions)\n    ]\n    shed_stock = {\n        item: max(0, int(quantity or 0))\n        for item, quantity in (private.get("shed", {}) or {}).items()\n    }\n    tours, undone = _v464.router.plan_day(\n        units,\n        tasks,\n        shed_stock=shed_stock,\n        fixed_owner=fixed_owner,\n        bank_outputs=liquidation,\n        deterministic_primal=True,\n    )\n    actions = [\n        _v463._route_action(farm, private, tours.get(index), index)\n        for index in range(len(positions))\n    ]\n\n    available = [\n        task for task in undone\n        if not task.carry and task.ops and float(task.value) > 0.0\n    ]\n    remaining_turns = max(0, 24 - hour)\n    for index, action in enumerate(actions):\n        if action != ["PASS"] or not available:\n            continue\n        position = tuple(positions[index])\n        feasible = [\n            task for task in available\n            if _c06._distance(position, task.pos) + task.n_ops\n            <= remaining_turns\n        ]\n        if not feasible:\n            continue\n        task = min(\n            feasible,\n            key=lambda candidate: (\n                _c06._distance(position, candidate.pos),\n                -float(candidate.value),\n                tuple(candidate.pos),\n                tuple(tuple(op) for op in candidate.ops),\n            ),\n        )\n        available.remove(task)\n        actions[index] = (\n            list(task.ops[0])\n            if position == tuple(task.pos)\n            else _c06._bfs_first_step(\n                farm["tiles"], position, tuple(task.pos)\n            )\n        )\n    return {\n        "farmer": actions[0] if actions else ["PASS"],\n        "hands": actions[1:],\n        "liquidation": liquidation,\n    }\n\n\n_v464._unit_actions = _unit_actions\n\n\ndef whitebox_v659_public_idle_undone_refill(obs):\n    return _v649.whitebox_v649_public_farmers_immediate_sales(obs)\n'
_BUNDLE_SOURCES['whitebox.versions.v675_public_wheat_slots12'] = '"""V675: reserve one extra crop tile only in the public wheat route.\n\nV659\'s sticky selector exposes a named ``wheat`` mode when the live rival farm\nhas a wheat-heavy, non-strawberry public crop book.  In that mode only, use\ntwelve animal slots instead of thirteen so one more already-unlocked tile\nremains a crop role.  Light and default routes are unchanged.\n"""\n\nfrom whitebox.versions import v659_public_idle_undone_refill as _v659\n\n\n_v623 = _v659._v649._v646._v645._v623\n_v623._WHEAT = {"NW": 4, "NE": 4, "SW": 4, "SE": 0}\n\n\ndef whitebox_v675_public_wheat_slots12(obs):\n    return _v659.whitebox_v659_public_idle_undone_refill(obs)\n'
_BUNDLE_SOURCES['whitebox.versions.v678_public_brunch_wheat_slots12'] = '"""V678: reserve the thirteenth wheat-route tile only for public brunch demand.\n\nThe wheat route benefits from one extra crop role when the live town has\nunlocked BRUNCH_SPOT, whose public recipe consumes both wheat and strawberry.\nUse V675\'s twelve animal slots only in that state; otherwise retain the\nthirteen-slot wheat portfolio.  Light/default routes and every other decision\nremain unchanged.\n"""\n\nfrom whitebox.versions import v675_public_wheat_slots12 as _v675\n\n\n_v623 = _v675._v623\n_WHEAT_12 = {"NW": 4, "NE": 4, "SW": 4, "SE": 0}\n_WHEAT_13 = {"NW": 4, "NE": 5, "SW": 4, "SE": 0}\n\n\ndef whitebox_v678_public_brunch_wheat_slots12(obs):\n    shops = ((obs or {}).get("town", {}) or {}).get(\n        "unlocked_shops", []\n    ) or []\n    _v623._WHEAT = dict(\n        _WHEAT_12 if "BRUNCH_SPOT" in shops else _WHEAT_13\n    )\n    return _v675.whitebox_v675_public_wheat_slots12(obs)\n'
_BUNDLE_SOURCES['whitebox.versions.v684_public_recertified_nonfarmers_light'] = '"""V684: recertify non-FARMERS light routes from the live public economy.\n\nV678\'s FARMERS_MARKET light route has a dedicated carried-input solver and\nlate crop rotation, so its initial public certificate remains stable.  Other\nlight routes use the ordinary matcher: if the visible rival later ceases to\nbe low-wheat, or the public wool price falls below milk, the original reason\nfor the reduced livestock footprint no longer holds.  Permanently return\nthat episode to the default route using only the current farms and market.\n"""\n\nfrom whitebox.versions import v678_public_brunch_wheat_slots12 as _v678\nfrom whitebox.versions import v608_public_sticky_low_wheat_route as _v608\n\n\n_v545 = _v608._v545\n_sticky_update_mode = _v545._update_mode\n\n\ndef _farmers_market(obs):\n    shops = ((obs or {}).get("town", {}) or {}).get(\n        "unlocked_shops", []\n    ) or []\n    return "FARMERS_MARKET" in shops\n\n\ndef _update_mode(obs):\n    mode = _sticky_update_mode(obs)\n    if mode != "light" or _farmers_market(obs):\n        return mode\n    if _v608._low_wheat_animals(obs) and _v608._wool_favorable(obs):\n        return mode\n    player = int((obs or {}).get("player", 0) or 0)\n    _v545._MODE[player] = "default"\n    return "default"\n\n\n_v545._update_mode = _update_mode\n\n\ndef whitebox_v684_public_recertified_nonfarmers_light(obs):\n    return _v678.whitebox_v678_public_brunch_wheat_slots12(obs)\n'
_BUNDLE_SOURCES['whitebox.versions.v698_public_farmers_cow7'] = '"""V698: seven cows in the public FARMERS_MARKET light portfolio.\n\nV684\'s live light route produces enough wool from its seven sheep but trails\nthe public milk route.  Preserve its thirteen livestock cells and every route,\ncrop, market, and hiring rule; only exchange one sheep role for one cow while\nthe current public certificate is light plus FARMERS_MARKET.\n"""\n\nfrom whitebox.versions import v684_public_recertified_nonfarmers_light as _v684\n\n\n_v678 = _v684._v678\n_v645 = _v678._v675._v659._v649._v646._v645\n_v545 = _v645._v545\n_c06 = _v645._c06\n_base_targets = _c06._herd_targets\n\n\ndef _herd_targets(obs, farm, private, capacity):\n    raw = _base_targets(obs, farm, private, capacity)\n    player = int((obs or {}).get("player", 0) or 0)\n    if (\n        _v545._MODE.get(player) != "light"\n        or not _v645._farmers_market(obs)\n    ):\n        return raw\n    total = min(int(capacity), sum(raw.values()), 13)\n    if total < 4:\n        return raw\n    cows = min(total, 7)\n    return {"COW": cows, "SHEEP": max(0, total - cows)}\n\n\n_c06._herd_targets = _herd_targets\n\n\ndef whitebox_v698_public_farmers_cow7(obs):\n    return _v684.whitebox_v684_public_recertified_nonfarmers_light(obs)\n'

class _WhiteboxBundleLoader(_bundle_abc.Loader):
    def create_module(self, spec):
        return None

    def exec_module(self, module):
        name = module.__spec__.name
        filename = '<whitebox-bundle>/' + name.replace('.', '/') + '.py'
        module.__file__ = filename
        exec(compile(_BUNDLE_SOURCES[name], filename, 'exec'), module.__dict__)


class _WhiteboxBundleFinder(_bundle_abc.MetaPathFinder):
    def find_spec(self, fullname, path=None, target=None):
        if fullname not in _BUNDLE_SOURCES:
            return None
        return _bundle_util.spec_from_loader(
            fullname, _WhiteboxBundleLoader(),
            is_package=fullname in _BUNDLE_PACKAGES)


_bundle_sys.meta_path.insert(0, _WhiteboxBundleFinder())
from whitebox.versions.v698_public_farmers_cow7 import whitebox_v698_public_farmers_cow7 as _WHITEBOX_ENTRY


def kaggriculture_agent(observation, configuration=None):
    # The modular white-box API depends only on the live observation.
    return _WHITEBOX_ENTRY(observation)
